/* Prüfungs-Pool Industriemechaniker im Stil der gestreckten Abschlussprüfung (Teil 1; Teil 2 Auftrags- und Funktionsanalyse, Fertigungstechnik).
   Eigene Formulierungen und eigene Zahlen (KI-Entwurf, Rechenfragen mit einem Prüfskript nachgerechnet; Freigabe durch den Ausbilder steht aus, keine Originalaufgaben).
   Form wie pruefpool.js: { id, teil, g, th, n, q, w, o, r } (Mehrfachwahl) oder { id, teil, g, th, n, q, w, ans, u, tol } (Zahleneingabe). teil: IM1, IMA, IMF.
   Wirtschafts- und Sozialkunde steht in pruefpool.js (teil WiSo). Erzeugt aus _w187/im/pruef/quelle (bau.js), nicht von Hand ändern. */
window.PR_POOL_IM = {"teile":[{"k":"IM1","t":"Teil 1","lang":"Abschlussprüfung Teil 1"},{"k":"IMA","t":"Teil 2: Auftrags- und Funktionsanalyse","lang":"Abschlussprüfung Teil 2: Auftrags- und Funktionsanalyse"},{"k":"IMF","t":"Teil 2: Fertigungstechnik","lang":"Abschlussprüfung Teil 2: Fertigungstechnik"}],"groups":[{"k":"imtk","teil":"IM1","t":"Technische Kommunikation","icon":"📐","lab":"zei","labN":"Zeichnungs-Lab"},{"k":"imft","teil":"IM1","t":"Fertigungstechnik: Spanen von Hand und mit Maschinen","icon":"⚙️","lab":"zer","labN":"Zerspan-Lab"},{"k":"impt","teil":"IM1","t":"Prüftechnik","icon":"📏","lab":"tol","labN":"Toleranz-Lab"},{"k":"imwt","teil":"IM1","t":"Werkstofftechnik","icon":"🧱","lab":"wer","labN":"Werkstoff-Lab"},{"k":"imfu","teil":"IM1","t":"Fügen","icon":"🔩","lab":"fug","labN":"Füge-Lab"},{"k":"imas","teil":"IM1","t":"Arbeitssicherheit und Umweltschutz","icon":"🦺","lab":"","labN":""},{"k":"imst","teil":"IM1","t":"Steuerungstechnik: Pneumatik-Grundschaltungen","icon":"💨","lab":"pne","labN":"Pneumatik-Lab"},{"k":"immt","teil":"IM1","t":"Technische Mathematik","icon":"🧮","lab":"mat","labN":"Rechen-Lab"},{"k":"imme","teil":"IMA","t":"Maschinenelemente","icon":"🛞","lab":"mas","labN":"Maschinenelemente-Lab"},{"k":"imgt","teil":"IMA","t":"Getriebe und Übersetzung","icon":"⚙️","lab":"mas","labN":"Maschinenelemente-Lab"},{"k":"imph","teil":"IMA","t":"Pneumatik und Hydraulik","icon":"🛠️","lab":"hyd","labN":"Hydraulik-Lab"},{"k":"imsp","teil":"IMA","t":"Elektropneumatik und SPS","icon":"🎛","lab":"pne","labN":"Pneumatik-Lab"},{"k":"imap","teil":"IMF","t":"Arbeitsplanung","icon":"📋","lab":"fer","labN":"Fertigungs-Lab"},{"k":"imcn","teil":"IMF","t":"CNC-Grundlagen","icon":"🖥","lab":"cnc","labN":"CNC-Lab"},{"k":"immo","teil":"IMF","t":"Montage und Demontage","icon":"🔧","lab":"mas","labN":"Maschinenelemente-Lab"},{"k":"imih","teil":"IMF","t":"Instandhaltung","icon":"🧰","lab":"ins","labN":"Instandhaltungs-Lab"},{"k":"imqm","teil":"IMF","t":"Qualitätsmanagement und Prüfmittel","icon":"✅","lab":"tol","labN":"Toleranz-Lab"}],"q":[{"id":"IM-tk-01","teil":"IM1","g":"imtk","th":"Linienarten","n":1,"q":"Mit welcher Linienart werden sichtbare Kanten und Umrisse eines Werkstücks gezeichnet?","w":"Sichtbare Kanten und Umrisse sind breite Volllinien. Schmale Volllinien dienen für Maßlinien und Schraffuren, Strichlinien für verdeckte Kanten, Strichpunktlinien für Mittellinien.","o":["Schmale Volllinie","Schmale Strichlinie","Schmale Strichpunktlinie","Breite Volllinie"],"r":3},{"id":"IM-tk-02","teil":"IM1","g":"imtk","th":"Linienarten","n":1,"q":"Wofür wird die schmale Strichlinie in einer technischen Zeichnung verwendet?","w":"Die Strichlinie zeigt Kanten, die in der Ansicht verdeckt liegen. Mittellinien sind Strichpunktlinien, Maßlinien schmale Volllinien.","o":["Für verdeckte Kanten und Umrisse","Für Mittellinien und Symmetrieachsen","Für Maßlinien und Maßhilfslinien","Für den Verlauf einer Schnittebene"],"r":0},{"id":"IM-tk-03","teil":"IM1","g":"imtk","th":"Maßstab","n":1,"q":"Ein Maschinengestell ist im Maßstab 1:5 gezeichnet. Eine Strebe ist in der Zeichnung 36 mm lang. Wie lang ist die Strebe in Wirklichkeit?","w":"Maßstab 1:5 bedeutet fünffach verkleinert: 36 mm · 5 = 180 mm.","o":["7,2 mm","180 mm","41 mm","90 mm"],"r":1},{"id":"IM-tk-04","teil":"IM1","g":"imtk","th":"Ansichten","n":2,"q":"Wo steht bei der Projektionsmethode 1 die Seitenansicht von links?","w":"Bei der Projektionsmethode 1 wird das Werkstück gedanklich geklappt: Die Ansicht von links steht rechts, die Draufsicht steht unter der Vorderansicht.","o":["Links neben der Vorderansicht","Über der Vorderansicht","Rechts neben der Vorderansicht","Unter der Vorderansicht"],"r":2},{"id":"IM-tk-05","teil":"IM1","g":"imtk","th":"Maßeintragung","n":2,"q":"Was bedeutet die Maßangabe SR 20 in einer Zeichnung?","w":"S steht für Kugel (englisch sphere), R für Radius. Die Schlüsselweite wird mit SW angegeben, Rauheiten mit Ra oder Rz.","o":["Schlüsselweite 20 mm","Senkungsradius einer Bohrung mit 20 mm Tiefe","Rautiefe 20 µm","Kugelradius 20 mm"],"r":3},{"id":"IM-tk-06","teil":"IM1","g":"imtk","th":"Gewindeangaben","n":2,"q":"Was bedeutet die Angabe M10x1 an einem Gewinde?","w":"Wird hinter dem Nenndurchmesser eine Steigung genannt, ist es ein Feingewinde. Das Regelgewinde M10 hat 1,5 mm Steigung und wird ohne Steigung angegeben. Linksgewinde tragen den Zusatz LH.","o":["Metrisches Feingewinde mit 10 mm Nenndurchmesser und 1 mm Steigung","Metrisches Regelgewinde mit 10 mm Nenndurchmesser und 1 mm Gewindelänge","Metrisches Gewinde mit 10 Gewindegängen je Millimeter","Metrisches Linksgewinde mit 10 mm Nenndurchmesser, eingängig"],"r":0},{"id":"IM-tk-07","teil":"IM1","g":"imtk","th":"Toleranzen","n":1,"q":"Ein Maß ist mit 25 +0,1/-0,2 eingetragen. Wie groß ist die Maßtoleranz?","w":"Höchstmaß 25,1 mm, Mindestmaß 24,8 mm. Toleranz = Höchstmaß - Mindestmaß = 0,3 mm.","o":["0,1 mm","0,3 mm","0,2 mm","0,15 mm"],"r":1},{"id":"IM-tk-08","teil":"IM1","g":"imtk","th":"Allgemeintoleranzen","n":2,"q":"Für Längenmaße über 30 mm bis 120 mm gilt in der Toleranzklasse m (mittel) das Grenzabmaß ±0,3 mm. Zwischen welchen Grenzen darf das Maß 80 ohne eigene Toleranzangabe liegen?","w":"Das Grenzabmaß gilt nach beiden Seiten: 80 - 0,3 = 79,7 mm und 80 + 0,3 = 80,3 mm.","o":["79,85 mm bis 80,15 mm","80,0 mm bis 80,3 mm","79,7 mm bis 80,3 mm","79,4 mm bis 80,6 mm"],"r":2},{"id":"IM-tk-09","teil":"IM1","g":"imtk","th":"Passungen","n":2,"q":"Eine Bohrung Ø30 H7 hat die Abmaße 0 und +21 µm, die Welle Ø30 f7 die Abmaße -20 µm und -41 µm. Wie groß ist das Höchstspiel?","w":"Höchstspiel = größte Bohrung - kleinste Welle = 30,021 mm - 29,959 mm = 0,062 mm. Das Mindestspiel beträgt 0,020 mm.","o":["0,020 mm","0,041 mm","0,021 mm","0,062 mm"],"r":3},{"id":"IM-tk-10","teil":"IM1","g":"imtk","th":"Passungssysteme","n":2,"q":"Was kennzeichnet das Passungssystem Einheitsbohrung?","w":"Bei der Einheitsbohrung ist das untere Abmaß der Bohrung null (H). Spiel, Übergang oder Übermaß entstehen durch die Wahl der Welle. So genügen wenige Reibahlen und Lehrdorne.","o":["Alle Wellen haben das Grundabmaß h, die Passungsart wird über die Bohrung gewählt","Bohrung und Welle erhalten immer dieselbe Toleranzklasse","Alle Bohrungen einer Maschine haben denselben Nenndurchmesser","Alle Bohrungen haben das Grundabmaß H, die Passungsart wird über die Toleranzklasse der Welle gewählt"],"r":3},{"id":"IM-tk-11","teil":"IM1","g":"imtk","th":"Oberflächen","n":1,"q":"Welche Kenngröße wird mit Ra angegeben?","w":"Ra ist der arithmetische Mittelwert der Profilabweichungen von der Mittellinie. Die gemittelte Rautiefe heißt Rz.","o":["Die gemittelte Rautiefe","Die größte Einzelrautiefe","Der arithmetische Mittenrauwert","Die Welligkeit der Oberfläche"],"r":2},{"id":"IM-tk-12","teil":"IM1","g":"imtk","th":"Schnittdarstellung","n":2,"q":"Welche Teile werden in einer Schnittdarstellung in Längsrichtung nicht geschnitten gezeichnet?","w":"Volle Normteile und Vollwellen haben kein Inneres, das ein Schnitt zeigen könnte. Sie werden in Längsrichtung in Ansicht gezeichnet. Hohle Teile wie Buchsen oder Gehäuse werden geschnitten.","o":["Gehäuse und Deckel","Schrauben, Stifte, Passfedern und Vollwellen","Buchsen und Hülsen","Lagerschalen und Flansche"],"r":1},{"id":"IM-tk-13","teil":"IM1","g":"imtk","th":"Gewindedarstellung","n":2,"q":"Wie wird ein Außengewinde (Bolzengewinde) in der Seitenansicht dargestellt?","w":"Beim Bolzen ist der Außendurchmesser die sichtbare Körperkante (breit). Der Gewindegrund wird schmal gezeichnet. Beim Innengewinde im Schnitt ist es umgekehrt.","o":["Außendurchmesser als breite Volllinie, Kerndurchmesser als schmale Volllinie","Außendurchmesser als schmale Volllinie, Kerndurchmesser als breite Volllinie","Beide Durchmesser als breite Volllinie","Außendurchmesser als breite Volllinie, Kerndurchmesser als Strichpunktlinie"],"r":0},{"id":"IM-tk-14","teil":"IM1","g":"imtk","th":"Form- und Lagetoleranzen","n":2,"q":"In einem Toleranzrahmen steht als Symbol ein Paar paralleler Schrägstriche (//), dahinter 0,05 und der Buchstabe A. Was wird toleriert?","w":"Die beiden Schrägstriche stehen für Parallelität, eine Richtungstoleranz mit Bezugselement. Ebenheit ist eine Formtoleranz und braucht keinen Bezug.","o":["Die Rechtwinkligkeit zum Bezug A innerhalb von 0,05 mm","Die Ebenheit der Fläche A innerhalb von 0,05 mm","Die Rauheit der Fläche A mit 0,05 µm","Die Parallelität zum Bezug A innerhalb von 0,05 mm"],"r":3},{"id":"IM-tk-15","teil":"IM1","g":"imtk","th":"Schnittdarstellung","n":2,"q":"Was zeigt ein Halbschnitt?","w":"Der Halbschnitt zeigt in einem Bild die äußere Form und den inneren Aufbau. Die Mittellinie trennt Ansicht und Schnitt.","o":["Ein Werkstück, das auf halber Länge abgebrochen dargestellt ist","Nur die halbe Stückzahl der Bauteile einer Baugruppe","Bei einem symmetrischen Werkstück eine Hälfte in Ansicht und die andere Hälfte im Schnitt","Einen Schnitt, der nur bis zur halben Werkstücktiefe schraffiert wird"],"r":2},{"id":"IM-tk-16","teil":"IM1","g":"imtk","th":"Maßeintragung","n":1,"q":"An einer Werkstückkante steht die Angabe 2x45°. Was bedeutet sie?","w":"Fasen unter 45° werden vereinfacht als Breite mal Winkel bemaßt.","o":["Zwei Bohrungen im Winkelabstand von 45°","Fase mit 2 mm Breite unter 45°","Rundung mit 2 mm Radius über 45°","Zwei Kanten, die um 45° geschwenkt werden"],"r":1},{"id":"IM-tk-17","teil":"IM1","g":"imtk","th":"Passungen","n":2,"q":"Für die Welle Ø40 h6 gelten die Abmaße 0 und -16 µm. Wie groß ist das Mindestmaß der Welle?","w":"Mindestmaß = Nennmaß + unteres Abmaß = 40 mm - 0,016 mm = 39,984 mm.","o":["39,984 mm","39,840 mm","40,016 mm","39,994 mm"],"r":0},{"id":"IM-tk-N01","teil":"IM1","g":"imtk","th":"Passungen","n":2,"q":"Eine Bohrung Ø20 hat die Abmaße 0 und +0,021 mm, die Welle die Abmaße -0,007 mm und -0,020 mm. Berechnen Sie das Höchstspiel in mm.","w":"Höchstspiel = 20,021 mm - 19,980 mm = 0,041 mm.","ans":0.041,"u":"mm","tol":0.02},{"id":"IM-ft-01","teil":"IM1","g":"imft","th":"Feilen","n":1,"q":"Was sagt die Hiebnummer einer Feile aus?","w":"Feilen mit kleiner Hiebnummer nehmen viel Werkstoff ab (Schruppen), Feilen mit hoher Hiebnummer erzeugen glatte Flächen (Schlichten).","o":["Je höher die Hiebnummer, desto länger ist die Feile","Je höher die Hiebnummer, desto gröber ist die Zahnteilung","Je höher die Hiebnummer, desto feiner ist die Zahnteilung","Die Hiebnummer nennt die Härte des Feilenwerkstoffs"],"r":2},{"id":"IM-ft-02","teil":"IM1","g":"imft","th":"Sägen","n":2,"q":"Ein dünnwandiges Stahlrohr soll von Hand gesägt werden. Welche Zahnteilung ist richtig?","w":"Bei dünnen Wänden würden grobe Zähne einhaken und ausbrechen. Es sollen stets mehrere Zähne gleichzeitig schneiden. Grobe Teilungen sind für weiche Werkstoffe und lange Schnittfugen.","o":["Eine grobe Zahnteilung, damit die Späne Platz haben","Eine feine Zahnteilung, damit immer mehrere Zähne im Eingriff sind","Die Zahnteilung spielt keine Rolle, nur die Blattlänge","Eine grobe Zahnteilung, damit der Schnitt schneller fertig ist"],"r":1},{"id":"IM-ft-03","teil":"IM1","g":"imft","th":"Sägen","n":1,"q":"Warum sind die Zähne eines Sägeblatts geschränkt oder gewellt?","w":"Durch das Freischneiden reibt das Blatt nicht an den Fugenwänden. Ohne Freischnitt würde es klemmen und heiß werden.","o":["Die Schnittfuge wird breiter als das Blatt, das Blatt klemmt nicht","Die Zähne werden dadurch härter","Das Blatt lässt sich leichter einspannen","Die Späne werden dadurch kürzer"],"r":0},{"id":"IM-ft-04","teil":"IM1","g":"imft","th":"Bohren","n":1,"q":"Welchen Spitzenwinkel hat ein üblicher Spiralbohrer (Typ N) für unlegierten Stahl?","w":"Der Standardbohrer Typ N hat 118° Spitzenwinkel. 60° und 90° sind Winkel von Zentrierspitzen und Senkern, 180° wäre eine ebene Stirn.","o":["60°","90°","180°","118°"],"r":3},{"id":"IM-ft-05","teil":"IM1","g":"imft","th":"Schnittdaten Bohren","n":2,"q":"Mit einem Bohrer Ø10 mm soll mit der Schnittgeschwindigkeit vc = 25 m/min gebohrt werden. Welche Drehzahl ist einzustellen?","w":"n = vc · 1000 / (π · d) = 25 · 1000 / (π · 10) ≈ 796 1/min. 1592 1/min ergibt sich, wenn der Radius statt des Durchmessers eingesetzt wird.","o":["etwa 80 1/min","etwa 250 1/min","etwa 796 1/min","etwa 1592 1/min"],"r":2},{"id":"IM-ft-06","teil":"IM1","g":"imft","th":"Senken","n":1,"q":"Welchen Senkwinkel braucht ein Kegelsenker für Senkschrauben mit metrischem Gewinde?","w":"Senkschrauben mit metrischem Gewinde haben einen Kopfwinkel von 90°. 60° wird zum Entgraten verwendet, 75° und 120° gehören zu Nietsenkungen.","o":["60°","90°","75°","120°"],"r":1},{"id":"IM-ft-07","teil":"IM1","g":"imft","th":"Reiben","n":2,"q":"Eine Bohrung Ø12 H7 soll hergestellt werden. Welche Arbeitsfolge ist richtig?","w":"Ein Spiralbohrer erreicht weder das Maß noch die Oberfläche einer H7-Bohrung. Die Reibahle braucht eine kleine Reibzugabe, deshalb wird mit Untermaß vorgebohrt.","o":["Mit Untermaß bohren (zum Beispiel Ø11,8 mm), ansenken, mit der Reibahle Ø12 H7 reiben","Direkt mit einem Spiralbohrer Ø12 mm bohren","Mit Ø12 mm bohren und anschließend mit der Reibahle Ø12 H7 reiben","Mit Ø11 mm bohren und mit dem Gewindebohrer M12 nacharbeiten"],"r":0},{"id":"IM-ft-08","teil":"IM1","g":"imft","th":"Reiben","n":2,"q":"Was ist beim Herausnehmen einer Handreibahle aus der Bohrung zu beachten?","w":"Beim Rückwärtsdrehen klemmen Späne zwischen Schneide und Bohrungswand. Die Schneiden brechen aus und die Oberfläche wird beschädigt.","o":["Sie wird rückwärts herausgedreht","Sie wird ohne Drehung mit einem Hammer herausgeschlagen","Sie wird abwechselnd vor und zurück gedreht","Sie wird in Schnittrichtung weitergedreht und dabei herausgezogen"],"r":3},{"id":"IM-ft-09","teil":"IM1","g":"imft","th":"Gewinde","n":1,"q":"Für ein Innengewinde M10 (Steigung 1,5 mm) wird das Kernloch gebohrt. Welchen Durchmesser hat der Bohrer nach der Faustformel Kernloch = Nenndurchmesser - Steigung?","w":"10 mm - 1,5 mm = 8,5 mm.","o":["10 mm","9,5 mm","8,5 mm","7,5 mm"],"r":2},{"id":"IM-ft-10","teil":"IM1","g":"imft","th":"Gewinde","n":1,"q":"In welcher Reihenfolge wird ein dreiteiliger Handgewindebohrersatz verwendet?","w":"Die Zerspanarbeit wird auf drei Werkzeuge verteilt. Der Vorschneider trägt einen Ring, der Mittelschneider zwei Ringe, der Fertigschneider keinen Ring.","o":["Fertigschneider, Mittelschneider, Vorschneider","Mittelschneider, Vorschneider, Fertigschneider","Vorschneider, Mittelschneider, Fertigschneider","Nur der Fertigschneider, die anderen dienen als Ersatz"],"r":2},{"id":"IM-ft-11","teil":"IM1","g":"imft","th":"Schnittdaten Drehen","n":2,"q":"Eine Welle mit Ø50 mm soll mit vc = 180 m/min überdreht werden. Welche Drehzahl ist einzustellen?","w":"n = vc · 1000 / (π · d) = 180 · 1000 / (π · 50) ≈ 1146 1/min.","o":["etwa 573 1/min","etwa 2292 1/min","etwa 115 1/min","etwa 1146 1/min"],"r":3},{"id":"IM-ft-12","teil":"IM1","g":"imft","th":"Drehen","n":1,"q":"Was geschieht beim Plandrehen?","w":"Plandrehen erzeugt ebene Flächen rechtwinklig zur Drehachse. Die Bewegung parallel zur Achse heißt Längsdrehen (Runddrehen).","o":["Der Drehmeißel bewegt sich quer zur Drehachse und erzeugt eine ebene Stirnfläche","Der Drehmeißel bewegt sich parallel zur Drehachse und erzeugt eine Zylinderfläche","Der Drehmeißel sticht eine Nut in den Umfang","Der Drehmeißel erzeugt ein Gewinde auf dem Umfang"],"r":0},{"id":"IM-ft-13","teil":"IM1","g":"imft","th":"Schneidengeometrie","n":2,"q":"Ein Drehmeißel hat den Freiwinkel α = 6° und den Spanwinkel γ = 12°. Wie groß ist der Keilwinkel β?","w":"Freiwinkel, Keilwinkel und Spanwinkel ergeben zusammen 90°: β = 90° - 6° - 12° = 72°.","o":["18°","72°","78°","84°"],"r":1},{"id":"IM-ft-14","teil":"IM1","g":"imft","th":"Fräsen","n":2,"q":"Was kennzeichnet das Gegenlauffräsen?","w":"Beim Gegenlauf wächst der Span vom Eintritt zum Austritt. Die Schnittkraft drückt gegen den Vorschub, daher ist das Verfahren auch für Tischantriebe mit Spiel geeignet.","o":["Die Schneide tritt mit der größten Spandicke ein, der Fräser zieht das Werkstück in Vorschubrichtung","Fräser und Werkstück drehen sich gegenläufig um dieselbe Achse","Die Schneide tritt mit der Spandicke null ein, die Vorschubrichtung des Werkstücks ist der Schnittrichtung entgegengesetzt","Es werden zwei Fräser eingesetzt, die gegeneinander laufen"],"r":2},{"id":"IM-ft-15","teil":"IM1","g":"imft","th":"Schnittdaten Fräsen","n":2,"q":"Ein Fräser mit z = 6 Schneiden läuft mit n = 500 1/min, der Vorschub je Zahn ist fz = 0,08 mm. Wie groß ist die Vorschubgeschwindigkeit?","w":"vf = fz · z · n = 0,08 mm · 6 · 500 1/min = 240 mm/min.","o":["40 mm/min","2400 mm/min","83 mm/min","240 mm/min"],"r":3},{"id":"IM-ft-16","teil":"IM1","g":"imft","th":"Hauptnutzungszeit","n":2,"q":"Eine Welle wird auf 120 mm Vorschubweg mit f = 0,2 mm und n = 800 1/min längsgedreht. Wie lang ist die Hauptnutzungszeit?","w":"th = L / (f · n) = 120 mm / (0,2 mm · 800 1/min) = 0,75 min.","o":["0,75 min","1,33 min","7,5 min","0,15 min"],"r":0},{"id":"IM-ft-17","teil":"IM1","g":"imft","th":"Schneidstoffe","n":2,"q":"Welchen Vorteil hat Hartmetall gegenüber Schnellarbeitsstahl (HSS)?","w":"Hartmetall hat eine höhere Warmhärte und Verschleißfestigkeit. Dafür ist es spröder und schlagempfindlicher als HSS.","o":["Es ist zäher und unempfindlich gegen Schläge","Es behält seine Härte bei höheren Temperaturen und erlaubt höhere Schnittgeschwindigkeiten","Es lässt sich leichter von Hand nachschleifen","Es ist bei gleicher Größe immer preiswerter"],"r":1},{"id":"IM-ft-18","teil":"IM1","g":"imft","th":"Schruppen und Schlichten","n":1,"q":"Welche Einstellung passt zum Schlichten beim Drehen?","w":"Beim Schlichten zählen Maßgenauigkeit und Oberfläche. Beim Schruppen soll in kurzer Zeit viel Werkstoff abgetragen werden.","o":["Großer Vorschub, große Schnitttiefe, niedrige Schnittgeschwindigkeit","Großer Vorschub, kleine Schnitttiefe, niedrige Schnittgeschwindigkeit","Kleiner Vorschub, kleine Schnitttiefe, hohe Schnittgeschwindigkeit","Kleiner Vorschub, große Schnitttiefe, niedrige Schnittgeschwindigkeit"],"r":2},{"id":"IM-ft-19","teil":"IM1","g":"imft","th":"Spanbildung","n":3,"q":"Was ist eine Aufbauschneide?","w":"Aufbauschneiden entstehen vor allem bei zähen Werkstoffen und niedriger Schnittgeschwindigkeit. Sie reißen immer wieder ab und hinterlassen eine raue Oberfläche.","o":["Eine zusätzlich aufgelötete Schneide für höhere Standzeit","Eine Beschichtung, die die Schneide vor Verschleiß schützt","Die zweite Schneide eines Wendeschneidplattenhalters","Werkstoff, der sich bei zu niedriger Schnittgeschwindigkeit auf der Schneide festschweißt und die Oberfläche verschlechtert"],"r":3},{"id":"IM-ft-20","teil":"IM1","g":"imft","th":"Spannen","n":2,"q":"Ein unrundes Gussteil soll auf der Drehmaschine so gespannt werden, dass eine außermittige Bohrung rund läuft. Welches Spannmittel eignet sich?","w":"Mit einzeln verstellbaren Backen lässt sich das Werkstück beliebig ausrichten. Dreibackenfutter und Spannzange zentrieren selbsttätig auf die Außenform.","o":["Selbstzentrierendes Dreibackenfutter","Vierbackenfutter mit einzeln verstellbaren Backen","Spannzange","Spannen zwischen Spitzen mit Mitnehmer"],"r":1},{"id":"IM-ft-21","teil":"IM1","g":"imft","th":"Anreißen und Körnen","n":1,"q":"Wozu wird die Bohrungsmitte vor dem Bohren gekörnt?","w":"Die Querschneide des Bohrers schneidet nicht, sie drückt. Ohne Körnung wandert der Bohrer auf der Oberfläche.","o":["Die Bohrerspitze wird geführt und der Bohrer verläuft nicht","Der Werkstoff wird an der Stelle gehärtet","Die Bohrung wird dadurch maßgenau","Das Kühlschmiermittel sammelt sich in der Vertiefung"],"r":0},{"id":"IM-ft-22","teil":"IM1","g":"imft","th":"Bohren","n":2,"q":"Warum wird eine Bohrung mit großem Durchmesser vorgebohrt?","w":"Die Querschneide verdrängt den Werkstoff nur. Vorgebohrt wird etwa mit dem Durchmesser der Querschneidenlänge des großen Bohrers.","o":["Der große Bohrer schneidet dann mit höherer Schnittgeschwindigkeit","Die Bohrung wird dadurch länger","Der große Bohrer muss dann nicht mehr gekühlt werden","Die Querschneide des großen Bohrers muss dann nicht quetschen, die Vorschubkraft sinkt"],"r":3},{"id":"IM-ft-23","teil":"IM1","g":"imft","th":"Oberfläche beim Drehen","n":3,"q":"Die theoretische Rautiefe beim Drehen lässt sich mit Rth ≈ f² / (8 · r) abschätzen. Wie groß ist sie bei f = 0,2 mm und einem Eckenradius r = 0,8 mm?","w":"Rth = (0,2 mm)² / (8 · 0,8 mm) = 0,04 / 6,4 mm = 0,00625 mm = 6,25 µm.","o":["etwa 62,5 µm","etwa 0,625 µm","etwa 6,25 µm","etwa 25 µm"],"r":2},{"id":"IM-ft-24","teil":"IM1","g":"imft","th":"Fräsen","n":2,"q":"Bei welchem Fräsverfahren steht die Fräserachse senkrecht zur erzeugten ebenen Fläche?","w":"Beim Stirnfräsen, zum Beispiel mit dem Messerkopf, steht die Fräserachse senkrecht zur Fläche. Beim Umfangsfräsen liegt sie parallel dazu.","o":["Umfangsfräsen","Stirnfräsen","Nutenfräsen mit dem Scheibenfräser","Wälzfräsen einer Verzahnung"],"r":1},{"id":"IM-ft-25","teil":"IM1","g":"imft","th":"Gewinde","n":2,"q":"Womit wird ein Außengewinde von Hand geschnitten?","w":"Das Schneideisen schneidet Bolzengewinde. Gewindebohrer mit Windeisen sind für Innengewinde. Der Bolzen wird vorher angefast.","o":["Mit dem Schneideisen im Schneideisenhalter","Mit dem Gewindebohrer im Windeisen","Mit der Reibahle","Mit dem Kegelsenker"],"r":0},{"id":"IM-ft-N01","teil":"IM1","g":"imft","th":"Schnittdaten Bohren","n":2,"q":"Mit einem Bohrer Ø12 mm soll mit der Schnittgeschwindigkeit vc = 30 m/min gebohrt werden. Berechnen Sie die Drehzahl in 1/min.","w":"n = vc · 1000 / (π · d) = 30 · 1000 / (π · 12) ≈ 796 1/min.","ans":795.8,"u":"1/min","tol":0.02},{"id":"IM-ft-N02","teil":"IM1","g":"imft","th":"Schnittdaten Fräsen","n":2,"q":"Ein Fräser mit 3 Schneiden läuft mit 1500 1/min, der Vorschub je Zahn beträgt 0,06 mm. Berechnen Sie die Vorschubgeschwindigkeit in mm/min.","w":"vf = fz · z · n = 0,06 mm · 3 · 1500 1/min = 270 mm/min.","ans":270,"u":"mm/min","tol":0.02},{"id":"IM-ft-N03","teil":"IM1","g":"imft","th":"Hauptnutzungszeit","n":2,"q":"Eine Bohrung wird mit dem Vorschubweg 80 mm, dem Vorschub 0,1 mm und der Drehzahl 400 1/min gebohrt. Berechnen Sie die Hauptnutzungszeit in min.","w":"th = L / (f · n) = 80 mm / (0,1 mm · 400 1/min) = 2 min.","ans":2,"u":"min","tol":0.02},{"id":"IM-ft-N04","teil":"IM1","g":"imft","th":"Schnittdaten Drehen","n":2,"q":"Eine Welle mit Ø80 mm läuft mit 600 1/min. Berechnen Sie die Schnittgeschwindigkeit in m/min.","w":"vc = π · d · n / 1000 = π · 80 · 600 / 1000 ≈ 150,8 m/min.","ans":150.8,"u":"m/min","tol":0.02},{"id":"IM-pt-01","teil":"IM1","g":"impt","th":"Messen und Lehren","n":1,"q":"Worin unterscheiden sich Messen und Lehren?","w":"Beim Messen wird das Istmaß als Zahl mit Einheit ermittelt. Eine Lehre verkörpert ein Maß oder eine Form und ergibt nur Gut oder Ausschuss.","o":["Messen liefert einen Zahlenwert, Lehren stellt nur fest, ob eine Grenze eingehalten ist","Messen ist immer genauer als Lehren","Lehren liefert einen Zahlenwert, Messen nur gut oder schlecht","Messen geschieht von Hand, Lehren mit einer Maschine"],"r":0},{"id":"IM-pt-02","teil":"IM1","g":"impt","th":"Messschieber","n":1,"q":"Welchen Noniuswert hat ein Messschieber mit 20 Noniusteilen (Nonius 1/20)?","w":"1 mm / 20 = 0,05 mm. Ein Nonius mit 10 Teilen zeigt 0,1 mm, mit 50 Teilen 0,02 mm.","o":["0,02 mm","0,1 mm","0,5 mm","0,05 mm"],"r":3},{"id":"IM-pt-03","teil":"IM1","g":"impt","th":"Bügelmessschraube","n":2,"q":"Die Spindel einer Bügelmessschraube hat 0,5 mm Steigung, die Trommel hat 50 Teilstriche. Welchem Weg entspricht ein Teilstrich?","w":"0,5 mm / 50 = 0,01 mm je Teilstrich.","o":["0,05 mm","0,001 mm","0,01 mm","0,5 mm"],"r":2},{"id":"IM-pt-04","teil":"IM1","g":"impt","th":"Bügelmessschraube","n":2,"q":"An einer Bügelmessschraube (Steigung 0,5 mm, 50 Teilstriche) sind auf der Hülse 7,5 mm sichtbar, die Trommel steht auf Teilstrich 23. Welches Maß wird abgelesen?","w":"7,5 mm + 23 · 0,01 mm = 7,73 mm.","o":["7,23 mm","7,73 mm","7,523 mm","9,8 mm"],"r":1},{"id":"IM-pt-05","teil":"IM1","g":"impt","th":"Lehren","n":2,"q":"Welche Aussage zum Grenzlehrdorn ist richtig?","w":"Die Gutseite (Mindestmaß) muss durch ihr Eigengewicht in die Bohrung gleiten. Die Ausschussseite (Höchstmaß, rot gekennzeichnet, kurz) darf höchstens anschnäbeln.","o":["Die Gutseite verkörpert das Mindestmaß der Bohrung und muss sich einführen lassen","Die Gutseite verkörpert das Höchstmaß der Bohrung","Die Ausschussseite muss sich leicht einführen lassen","Mit dem Grenzlehrdorn wird das Istmaß der Bohrung abgelesen"],"r":0},{"id":"IM-pt-06","teil":"IM1","g":"impt","th":"Lehren","n":2,"q":"Welches Maß verkörpert die Gutseite einer Grenzrachenlehre für Wellen?","w":"Eine Welle ist gut, wenn sie nicht größer als das Höchstmaß ist. Die Gutseite muss über die Welle gleiten, die Ausschussseite (Mindestmaß) darf es nicht.","o":["Das Mindestmaß der Welle","Das Nennmaß der Welle","Die Toleranz der Welle","Das Höchstmaß der Welle"],"r":3},{"id":"IM-pt-07","teil":"IM1","g":"impt","th":"Messuhr","n":2,"q":"Für welche Aufgabe eignet sich eine Messuhr mit Stativ besonders?","w":"Die Messuhr zeigt Abweichungen gegenüber einem eingestellten Ausgangswert. Sie eignet sich für Rundlauf, Planlauf, Parallelität und Vergleichsmessungen.","o":["Tiefe einer Sacklochbohrung direkt ablesen ohne Einstellen","Gewindesteigung bestimmen","Rundlauf einer Welle prüfen (Unterschiedsmessung)","Winkel einer Fase messen"],"r":2},{"id":"IM-pt-08","teil":"IM1","g":"impt","th":"Bezugstemperatur","n":1,"q":"Welche Bezugstemperatur gilt für Längenmessungen in der Fertigung?","w":"Werkstück und Prüfmittel dehnen sich mit der Temperatur aus. Maße in Zeichnungen gelten bei 20 °C.","o":["0 °C","20 °C","15 °C","25 °C"],"r":1},{"id":"IM-pt-09","teil":"IM1","g":"impt","th":"Messabweichungen","n":2,"q":"Wie entsteht ein Parallaxenfehler?","w":"Liegen Skale und Ablesemarke nicht in einer Ebene, verschiebt sich die Ablesung bei schrägem Blick. Abhilfe: senkrecht auf die Skale schauen.","o":["Die Skale wird schräg statt senkrecht abgelesen","Das Messgerät ist zu warm","Der Messdruck ist zu hoch","Die Messflächen sind verschmutzt"],"r":0},{"id":"IM-pt-10","teil":"IM1","g":"impt","th":"Messabweichungen","n":2,"q":"Welche Messabweichung ist systematisch?","w":"Systematische Abweichungen treten bei jeder Messung gleich auf und lassen sich berichtigen. Zufällige Abweichungen streuen und sind nicht vorhersagbar.","o":["Eine Messschraube, deren Nullstellung um 0,02 mm verstellt ist","Ein Span, der einmal zwischen die Messflächen gerät","Ein gelegentliches Verkanten des Messschiebers","Ein einmaliger Ablesefehler"],"r":0},{"id":"IM-pt-11","teil":"IM1","g":"impt","th":"Formprüfung","n":1,"q":"Wie wird mit einem Haarwinkel die Rechtwinkligkeit zweier Flächen geprüft?","w":"Schon sehr kleine Abweichungen zeigen sich als Lichtspalt zwischen Haarkante und Werkstück.","o":["Durch Ablesen an einer Gradskale","Nach dem Lichtspaltverfahren gegen eine helle Fläche","Durch Antasten mit einer Fühlerlehre von 1 mm","Durch Einfärben mit Tuschierfarbe und Hämmern"],"r":1},{"id":"IM-pt-12","teil":"IM1","g":"impt","th":"Endmaße","n":3,"q":"Das Maß 23,485 mm soll aus Parallelendmaßen zusammengesetzt werden. Womit beginnt man?","w":"Man beseitigt zuerst die kleinste Stelle. So entsteht die Kombination mit möglichst wenigen Endmaßen, zum Beispiel 1,005 + 1,48 + 1 + 20 mm.","o":["Mit dem größten Endmaß, hier 20 mm","Mit dem Endmaß 1 mm, weil es am häufigsten vorhanden ist","Mit dem Endmaß für die letzte Dezimalstelle, hier 1,005 mm","Die Reihenfolge ist beliebig, es zählt nur die Zahl der Endmaße"],"r":2},{"id":"IM-pt-13","teil":"IM1","g":"impt","th":"Innenmessung","n":2,"q":"Womit lässt sich der Durchmesser einer Bohrung Ø40 H7 als Zahlenwert am zuverlässigsten messen?","w":"Die Dreipunkt-Innenmessschraube zentriert sich selbst in der Bohrung und zeigt das Istmaß. Der Grenzlehrdorn liefert nur Gut oder Ausschuss.","o":["Mit dem Stahlmaßstab","Mit dem Grenzlehrdorn","Mit der Radienlehre","Mit einer Dreipunkt-Innenmessschraube"],"r":3},{"id":"IM-pt-N01","teil":"IM1","g":"impt","th":"Bügelmessschraube","n":1,"q":"An einer Bügelmessschraube (Steigung 0,5 mm, 50 Teilstriche) sind auf der Hülse 12,5 mm sichtbar, die Trommel steht auf Teilstrich 37. Welches Maß in mm wird abgelesen?","w":"12,5 mm + 37 · 0,01 mm = 12,87 mm.","ans":12.87,"u":"mm","tol":0.0002},{"id":"IM-wt-01","teil":"IM1","g":"imwt","th":"Eisenwerkstoffe","n":1,"q":"Bis zu welchem Kohlenstoffgehalt spricht man bei Eisenwerkstoffen von Stahl?","w":"Stahl enthält bis etwa 2 % Kohlenstoff (genauer 2,06 %). Darüber liegen die Gusseisenwerkstoffe.","o":["Bis etwa 0,2 %","Bis etwa 5 %","Bis etwa 10 %","Bis etwa 2 %"],"r":3},{"id":"IM-wt-02","teil":"IM1","g":"imwt","th":"Stahlbezeichnung","n":1,"q":"Was bedeutet die Bezeichnung C45?","w":"Bei unlegierten Stählen nennt die Zahl hinter C das Hundertfache des Kohlenstoffgehalts: 45 / 100 = 0,45 %.","o":["Unlegierter Stahl mit 0,45 % Kohlenstoff","Stahl mit 45 % Kohlenstoff","Stahl mit der Mindeststreckgrenze 45 N/mm²","Gusseisen mit 4,5 % Kohlenstoff"],"r":0},{"id":"IM-wt-03","teil":"IM1","g":"imwt","th":"Stahlbezeichnung","n":2,"q":"Beim niedriglegierten Stahl 42CrMo4 gilt für Chrom der Faktor 4. Wie hoch ist der Chromgehalt?","w":"Die Zahl hinter den Legierungselementen gehört zum ersten Element und wird durch den Faktor geteilt: 4 / 4 = 1 % Chrom. Die 42 steht für 0,42 % Kohlenstoff.","o":["etwa 4 %","etwa 1 %","etwa 16 %","etwa 0,42 %"],"r":1},{"id":"IM-wt-04","teil":"IM1","g":"imwt","th":"Stahlbezeichnung","n":2,"q":"Was bedeutet das X in der Bezeichnung X5CrNi18-10?","w":"Bei hochlegierten Stählen (ein Element über 5 %) stehen die Gehalte ohne Faktor: 0,05 % C, 18 % Chrom, 10 % Nickel. Es ist ein nichtrostender Stahl.","o":["Der Stahl ist nicht schweißbar","Der Stahl ist ein Gusswerkstoff","Hochlegierter Stahl, die Legierungsgehalte stehen direkt in Prozent","Der Stahl ist für Versuche bestimmt und nicht genormt"],"r":2},{"id":"IM-wt-05","teil":"IM1","g":"imwt","th":"Gusseisen","n":2,"q":"Was bedeutet die Bezeichnung EN-GJL-250?","w":"GJ steht für Gusseisen, L für Lamellengraphit. Kugelgraphit trägt das S (EN-GJS).","o":["Gusseisen mit Kugelgraphit, Mindestzugfestigkeit 250 N/mm²","Stahlguss mit 2,5 % Kohlenstoff","Gusseisen mit Lamellengraphit, Härte 250 HB","Gusseisen mit Lamellengraphit, Mindestzugfestigkeit 250 N/mm²"],"r":3},{"id":"IM-wt-06","teil":"IM1","g":"imwt","th":"Wärmebehandlung","n":2,"q":"Warum wird ein Werkstück nach dem Härten angelassen?","w":"Nach dem Abschrecken ist der Stahl glashart und spröde. Beim Anlassen (Wiedererwärmen) sinkt die Härte etwas, die Zähigkeit nimmt zu.","o":["Spannungen und Sprödigkeit nehmen ab, die Zähigkeit steigt","Die Härte steigt dadurch weiter an","Der Kohlenstoffgehalt wird erhöht","Die Oberfläche wird dadurch korrosionsbeständig"],"r":0},{"id":"IM-wt-07","teil":"IM1","g":"imwt","th":"Wärmebehandlung","n":2,"q":"Was versteht man unter Vergüten?","w":"Vergüten ergibt hohe Festigkeit bei guter Zähigkeit. Es wird für Wellen, Schrauben und Zahnräder aus Vergütungsstählen wie C45 oder 42CrMo4 angewendet.","o":["Glühen dicht unter der Schmelztemperatur","Härten mit anschließendem Anlassen bei hoher Temperatur","Aufkohlen der Randschicht ohne Abschrecken","Abkühlen im Ofen, damit der Stahl weich wird"],"r":1},{"id":"IM-wt-08","teil":"IM1","g":"imwt","th":"Wärmebehandlung","n":2,"q":"Welches Ziel hat das Einsatzhärten?","w":"Kohlenstoffarme Stähle wie 16MnCr5 werden in der Randschicht aufgekohlt und dann gehärtet. Der Kern bleibt zäh.","o":["Ein durchgehend hartes und sprödes Werkstück","Ein weiches, gut zerspanbares Gefüge","Eine harte, verschleißfeste Randschicht bei zähem Kern","Eine korrosionsbeständige Oberfläche"],"r":2},{"id":"IM-wt-09","teil":"IM1","g":"imwt","th":"Werkstoffprüfung","n":2,"q":"Was gibt die Streckgrenze Re eines Werkstoffs an?","w":"Bis zur Streckgrenze federt der Werkstoff elastisch zurück. Die größte Spannung im Zugversuch heißt Zugfestigkeit Rm, die bleibende Verlängerung Bruchdehnung A.","o":["Die Spannung, bei der die Probe reißt","Die größte Spannung im Zugversuch","Die Verlängerung der Probe in Prozent","Die Spannung, bei der die bleibende (plastische) Verformung beginnt"],"r":3},{"id":"IM-wt-10","teil":"IM1","g":"imwt","th":"Werkstoffprüfung","n":2,"q":"Ein Zugstab mit dem Querschnitt S = 50 mm² wird mit F = 15 kN belastet. Wie groß ist die Zugspannung?","w":"σ = F / S = 15 000 N / 50 mm² = 300 N/mm².","o":["30 N/mm²","750 N/mm²","3,3 N/mm²","300 N/mm²"],"r":3},{"id":"IM-wt-11","teil":"IM1","g":"imwt","th":"Härteprüfung","n":1,"q":"Bei welchem Härteprüfverfahren wird eine Diamantpyramide mit quadratischer Grundfläche eingedrückt?","w":"Brinell arbeitet mit einer Hartmetallkugel, Rockwell C mit einem Diamantkegel und misst die Eindringtiefe. Der Kerbschlagbiegeversuch prüft die Zähigkeit.","o":["Brinell (HBW)","Rockwell (HRC)","Vickers (HV)","Kerbschlagbiegeversuch"],"r":2},{"id":"IM-wt-12","teil":"IM1","g":"imwt","th":"Korrosion","n":2,"q":"Eine Stahlschraube sitzt in einem Kupferblech im Freien. Was geschieht bei Feuchtigkeit?","w":"Zwei verschiedene Metalle und ein Elektrolyt bilden ein galvanisches Element. Das unedlere Metall wird zerstört (Kontaktkorrosion).","o":["Das edlere Kupfer löst sich auf","Der unedlere Stahl korrodiert bevorzugt","Beide Metalle schützen sich gegenseitig","Es geschieht nichts, weil kein Strom angeschlossen ist"],"r":1},{"id":"IM-wt-13","teil":"IM1","g":"imwt","th":"Nichteisenmetalle","n":1,"q":"Warum ist Aluminium an der Luft recht korrosionsbeständig?","w":"Die dünne Oxidschicht schützt das darunterliegende Metall. Durch Eloxieren wird sie künstlich verstärkt.","o":["Es bildet eine dichte, festhaftende Oxidschicht","Es ist ein Edelmetall","Es enthält immer Chrom","Es nimmt keinen Sauerstoff auf"],"r":0},{"id":"IM-wt-14","teil":"IM1","g":"imwt","th":"Kunststoffe","n":1,"q":"Welche Kunststoffgruppe lässt sich durch Erwärmen wiederholt umformen und schweißen?","w":"Thermoplaste erweichen beim Erwärmen. Duroplaste sind eng vernetzt und zersetzen sich, Elastomere sind weitmaschig vernetzt und gummielastisch.","o":["Duroplaste","Elastomere","Keine, Kunststoffe zersetzen sich beim Erwärmen immer","Thermoplaste"],"r":3},{"id":"IM-wt-15","teil":"IM1","g":"imwt","th":"Nichteisenmetalle","n":1,"q":"Aus welchen Hauptbestandteilen besteht Messing?","w":"Messing ist eine Kupfer-Zink-Legierung. Kupfer und Zinn ergeben Zinnbronze.","o":["Kupfer und Zinn","Aluminium und Kupfer","Kupfer und Zink","Eisen und Zink"],"r":2},{"id":"IM-wt-16","teil":"IM1","g":"imwt","th":"Stahlsorten","n":2,"q":"Welche Eigenschaft haben Automatenstähle wie 11SMn30?","w":"Schwefel (teils auch Blei) lässt die Späne kurz brechen. Das ist für Drehautomaten wichtig. Die Schweißeignung ist dadurch schlechter.","o":["Sie sind besonders gut schweißbar","Sie bilden durch den Schwefelzusatz kurzbrechende Späne und lassen sich gut zerspanen","Sie sind nichtrostend","Sie sind ohne Wärmebehandlung glashart"],"r":1},{"id":"IM-wt-N01","teil":"IM1","g":"imwt","th":"Werkstoffprüfung","n":2,"q":"Ein Rundstab mit 10 mm Durchmesser wird mit 24 kN auf Zug belastet. Berechnen Sie die Zugspannung in N/mm².","w":"S = π · (10 mm)² / 4 = 78,54 mm². σ = 24 000 N / 78,54 mm² ≈ 305,6 N/mm².","ans":305.6,"u":"N/mm²","tol":0.02},{"id":"IM-fu-01","teil":"IM1","g":"imfu","th":"Schraubensicherung","n":2,"q":"Welches Element ist eine Losdrehsicherung für eine Schraubenverbindung?","w":"Klebstoff im Gewinde verbindet Schraube und Mutter und verhindert das Losdrehen. Eine flache Scheibe verteilt nur die Kraft, ein Sicherungsring hält Teile auf einer Welle fest, und eine größere Schlüsselweite ändert nur das Werkzeug.","o":["Mutter mit größerer Schlüsselweite","Flache Scheibe unter dem Schraubenkopf","Sicherungsring auf einer Welle","Mikroverkapselter Klebstoff im Gewinde"],"r":3},{"id":"IM-fu-02","teil":"IM1","g":"imfu","th":"Anziehdrehmoment","n":1,"q":"An einem Schraubenschlüssel mit 0,25 m wirksamer Länge wird mit 120 N rechtwinklig gezogen. Wie groß ist das Drehmoment?","w":"M = F · l = 120 N · 0,25 m = 30 N·m.","o":["30 N·m","480 N·m","3 N·m","300 N·m"],"r":0},{"id":"IM-fu-03","teil":"IM1","g":"imfu","th":"Festigkeitsklassen","n":2,"q":"Welche Mindeststreckgrenze hat eine Schraube der Festigkeitsklasse 10.9?","w":"Erste Zahl · 100 = Zugfestigkeit: 1000 N/mm². Zweite Zahl · 10 = Streckgrenze in Prozent der Zugfestigkeit: 90 % von 1000 N/mm² = 900 N/mm².","o":["1000 N/mm²","900 N/mm²","109 N/mm²","90 N/mm²"],"r":1},{"id":"IM-fu-04","teil":"IM1","g":"imfu","th":"Stifte","n":2,"q":"Welcher Stift kann ohne Reiben in eine nur gebohrte Bohrung eingeschlagen werden?","w":"Der geschlitzte Spannstift federt und gleicht die Bohrungstoleranz aus. Zylinder- und Kegelstifte brauchen geriebene Bohrungen.","o":["Zylinderstift mit Toleranz m6","Kegelstift","Spannstift (Spannhülse)","Gehärteter Passstift"],"r":2},{"id":"IM-fu-05","teil":"IM1","g":"imfu","th":"Stifte","n":2,"q":"Ein Kegelstift hat die Kegelverjüngung 1:50. Um wie viel ändert sich der Durchmesser auf 50 mm Länge?","w":"Kegel 1:50 bedeutet: 1 mm Durchmesseränderung auf 50 mm Länge.","o":["0,5 mm","2 mm","50 mm","1 mm"],"r":3},{"id":"IM-fu-06","teil":"IM1","g":"imfu","th":"Stifte","n":1,"q":"Welche Hauptaufgabe hat ein Zylinderstift als Passstift zwischen zwei Bauteilen?","w":"Passstifte fixieren die Lage, damit Bauteile nach dem Lösen wieder genau zusammenfinden. Die Vorspannkraft kommt von den Schrauben.","o":["Er sichert die genaue Lage der Bauteile zueinander","Er erzeugt die Vorspannkraft der Verbindung","Er dichtet die Trennfuge ab","Er gleicht Fertigungstoleranzen durch Federn aus"],"r":0},{"id":"IM-fu-07","teil":"IM1","g":"imfu","th":"Kleben","n":2,"q":"Welche Beanspruchung ist für eine Klebverbindung am günstigsten?","w":"Klebstoffe tragen gut auf Schub über große Flächen. Schäl- und Spaltkräfte greifen nur an einer Linie an und reißen die Klebung auf.","o":["Schälung an einer Kante","Scherung (Schub) in einer großflächigen Überlappung","Spaltung durch eine Keilwirkung","Biegung einer stumpf gestoßenen Naht"],"r":1},{"id":"IM-fu-08","teil":"IM1","g":"imfu","th":"Kleben","n":1,"q":"Wie werden die Fügeflächen vor dem Kleben vorbereitet?","w":"Öl, Fett, Staub und lose Oxidschichten verhindern die Haftung. Entfettete Flächen dürfen nicht mehr mit bloßen Händen berührt werden.","o":["Dünn einölen, damit der Klebstoff verläuft","Polieren und mit der Hand glätten","Reinigen, entfetten und bei Bedarf aufrauen","Stark erwärmen, bis die Flächen anlaufen"],"r":2},{"id":"IM-fu-09","teil":"IM1","g":"imfu","th":"Löten","n":1,"q":"Welche Temperatur trennt Weichlöten und Hartlöten?","w":"Lote, die unter 450 °C schmelzen, sind Weichlote. Hartlote schmelzen darüber und ergeben festere Verbindungen.","o":["100 °C","1000 °C","1500 °C","450 °C (Liquidustemperatur des Lots)"],"r":3},{"id":"IM-fu-10","teil":"IM1","g":"imfu","th":"Löten","n":2,"q":"Welche Aufgabe hat das Flussmittel beim Löten?","w":"Lot benetzt nur metallisch blanke Flächen. Rückstände aggressiver Flussmittel müssen nach dem Löten entfernt werden.","o":["Es erhöht die Schmelztemperatur des Lots","Es kühlt die Lötstelle","Es ersetzt das Lot bei kleinen Lötspalten","Es löst Oxide und verhindert deren Neubildung, damit das Lot benetzt"],"r":3},{"id":"IM-fu-11","teil":"IM1","g":"imfu","th":"Löten","n":2,"q":"Warum soll der Lötspalt beim Spaltlöten eng sein (etwa 0,05 mm bis 0,2 mm)?","w":"In engen Spalten steigt das Lot auch gegen die Schwerkraft. Bei zu breiten Spalten reißt der Kapillardruck ab, die Naht wird lückenhaft.","o":["Ein enger Spalt braucht kein Flussmittel","Das Lot schmilzt in einem engen Spalt bei niedrigerer Temperatur","Das flüssige Lot wird durch die Kapillarwirkung in den Spalt gezogen","Die Bauteile verschweißen im engen Spalt von selbst"],"r":2},{"id":"IM-fu-12","teil":"IM1","g":"imfu","th":"Schlussarten","n":1,"q":"Welche Verbindung ist stoffschlüssig?","w":"Stoffschluss entsteht durch Schweißen, Löten und Kleben. Passfeder und Stift wirken formschlüssig, die vorgespannte Schraubenverbindung kraftschlüssig.","o":["Passfederverbindung","Lötverbindung","Schraubenverbindung","Stiftverbindung"],"r":1},{"id":"IM-fu-13","teil":"IM1","g":"imfu","th":"Schlussarten","n":2,"q":"Zwei Platten sind mit Durchsteckschrauben fest verspannt. Wodurch werden Querkräfte in dieser Verbindung übertragen?","w":"Die Vorspannkraft presst die Platten aufeinander. Die Reibkraft in der Trennfuge nimmt die Querkraft auf, der Schraubenschaft soll nicht auf Abscheren belastet werden.","o":["Durch die Reibung zwischen den verspannten Platten (Kraftschluss)","Durch die Gewindeflanken, die auf Biegung beansprucht werden","Durch den Schraubenkopf, der sich in die Platte eingräbt","Durch den Stoffschluss im Gewinde"],"r":0},{"id":"IM-fu-14","teil":"IM1","g":"imfu","th":"Schweißen","n":2,"q":"Was kennzeichnet das MAG-Schweißen?","w":"MAG steht für Metall-Aktivgas. Das Schutzgas (CO2 oder Mischgas) reagiert mit dem Schmelzbad. Das Verfahren wird für unlegierte und niedriglegierte Stähle verwendet.","o":["Nicht abschmelzende Wolframelektrode unter Argon","Umhüllte Stabelektrode ohne Schutzgas","Brenngas-Sauerstoff-Flamme mit Schweißstab","Abschmelzende Drahtelektrode unter aktivem Schutzgas"],"r":3},{"id":"IM-fu-15","teil":"IM1","g":"imfu","th":"Schweißen","n":2,"q":"Was kennzeichnet das WIG-Schweißen?","w":"WIG steht für Wolfram-Inertgas. Das Schutzgas ist meist Argon. Zusatzwerkstoff wird bei Bedarf von Hand zugeführt.","o":["Abschmelzender Draht unter CO2","Umhüllte Stabelektrode, die Schlacke bildet","Lichtbogen zwischen einer nicht abschmelzenden Wolframelektrode und dem Werkstück unter inertem Gas","Widerstandserwärmung zwischen zwei Kupferelektroden"],"r":2},{"id":"IM-fu-16","teil":"IM1","g":"imfu","th":"Schweißen","n":2,"q":"Welche Aufgabe hat die Umhüllung einer Stabelektrode beim Lichtbogenhandschweißen?","w":"Gas und Schlacke schützen das Schmelzbad vor der Luft. Die Schlacke formt außerdem die Naht und verlangsamt die Abkühlung.","o":["Sie isoliert den Schweißer gegen die Schweißspannung","Sie bildet Schutzgas und Schlacke und stabilisiert den Lichtbogen","Sie kühlt die Elektrode","Sie verhindert das Abschmelzen des Kerndrahts"],"r":1},{"id":"IM-fu-N01","teil":"IM1","g":"imfu","th":"Anziehdrehmoment","n":1,"q":"An einem Schraubenschlüssel mit 0,3 m wirksamer Länge wird mit 200 N rechtwinklig gezogen. Berechnen Sie das Drehmoment in N·m.","w":"M = F · l = 200 N · 0,3 m = 60 N·m.","ans":60,"u":"N·m","tol":0.02},{"id":"IM-as-01","teil":"IM1","g":"imas","th":"Sicherheitszeichen","n":1,"q":"Welche Form und Farbe hat ein Gebotszeichen?","w":"Gebotszeichen sind blau und rund, zum Beispiel Gehörschutz benutzen. Gelbe Dreiecke warnen, rote Kreise mit Schrägbalken verbieten, grüne Rechtecke kennzeichnen Rettung und Erste Hilfe.","o":["Dreieckig, gelb mit schwarzem Rand","Rund, weiß mit rotem Rand und Schrägbalken","Rund, blau mit weißem Symbol","Rechteckig, grün mit weißem Symbol"],"r":2},{"id":"IM-as-02","teil":"IM1","g":"imas","th":"Sicherheitszeichen","n":1,"q":"Welche Bedeutung hat ein gelbes, dreieckiges Schild mit schwarzem Rand und schwarzem Symbol?","w":"Warnzeichen sind gelbe Dreiecke, zum Beispiel Warnung vor elektrischer Spannung.","o":["Gebot, eine Schutzausrüstung zu tragen","Warnung vor einer Gefahr","Verbot einer Handlung","Hinweis auf einen Rettungsweg"],"r":1},{"id":"IM-as-03","teil":"IM1","g":"imas","th":"Schutzmaßnahmen","n":2,"q":"In welcher Rangfolge werden Schutzmaßnahmen festgelegt?","w":"Die Gefahr an der Quelle zu beseitigen wirkt am zuverlässigsten. Persönliche Schutzausrüstung ist das letzte Mittel, weil sie vom Verhalten abhängt.","o":["Gefahr vermeiden oder ersetzen, dann technische, dann organisatorische, zuletzt persönliche Schutzmaßnahmen","Zuerst persönliche Schutzausrüstung, dann organisatorische, zuletzt technische Maßnahmen","Zuerst Unterweisung, dann persönliche Schutzausrüstung, technische Maßnahmen nur bei Unfällen","Die Rangfolge ist frei wählbar, wenn alle Beschäftigten zustimmen"],"r":0},{"id":"IM-as-04","teil":"IM1","g":"imas","th":"Maschinenarbeit","n":1,"q":"Was darf beim Arbeiten an der Ständerbohrmaschine nicht getragen werden?","w":"Handschuhe, lose Ärmel, Schmuck und offene lange Haare können von der Spindel erfasst und aufgewickelt werden.","o":["Schutzbrille","Eng anliegende Kleidung","Sicherheitsschuhe","Handschuhe"],"r":3},{"id":"IM-as-05","teil":"IM1","g":"imas","th":"Verhalten bei Unfällen","n":1,"q":"Warum wird auch eine kleine Verletzung im Verbandbuch (Meldeblock) eingetragen?","w":"Der Eintrag belegt, dass sich der Unfall bei der Arbeit ereignet hat. Das ist wichtig, wenn sich zum Beispiel eine Wunde später entzündet.","o":["Damit der Verletzte eine Abmahnung erhält","Weil sonst kein Pflaster ausgegeben werden darf","Als Nachweis für die gesetzliche Unfallversicherung, falls Spätfolgen auftreten","Damit der Betrieb die Ausfallzeit vom Lohn abziehen kann"],"r":2},{"id":"IM-as-06","teil":"IM1","g":"imas","th":"Gefahrstoffe","n":2,"q":"Wo findet der Beschäftigte am Arbeitsplatz die Schutzmaßnahmen und Verhaltensregeln für den Umgang mit einem Gefahrstoff, zum Beispiel einem Kühlschmierstoff?","w":"Die Betriebsanweisung wird vom Arbeitgeber auf Grundlage des Sicherheitsdatenblatts erstellt. Sie nennt Gefahren, Schutzmaßnahmen, Verhalten im Gefahrfall, Erste Hilfe und Entsorgung.","o":["Im Arbeitsvertrag","In der Betriebsanweisung","In der Stückliste","Im Prüfprotokoll der Maschine"],"r":1},{"id":"IM-as-07","teil":"IM1","g":"imas","th":"Lärm","n":2,"q":"Ab welchem Tages-Lärmexpositionspegel muss Gehörschutz getragen werden?","w":"Ab 80 dB(A) stellt der Arbeitgeber Gehörschutz bereit, ab 85 dB(A) muss er getragen werden. Lärmschwerhörigkeit ist nicht heilbar.","o":["Ab 85 dB(A)","Ab 60 dB(A)","Ab 70 dB(A)","Erst ab 120 dB(A)"],"r":0},{"id":"IM-as-08","teil":"IM1","g":"imas","th":"Brandschutz","n":2,"q":"In einer Spänewanne brennen Magnesiumspäne. Wie wird gelöscht?","w":"Brennendes Leichtmetall zersetzt Wasser, dabei entsteht Wasserstoff: Explosionsgefahr. Auch Schaum und Emulsion enthalten Wasser. Geeignet ist nur Metallbrandpulver (Brandklasse D). Ob zusätzlich trockener Sand erlaubt ist, regelt die Betriebsanweisung.","o":["Mit Wasser im Vollstrahl","Mit einem Schaumlöscher","Mit Kühlschmieremulsion aus der Maschine","Mit Metallbrandpulver (Brandklasse D)"],"r":3},{"id":"IM-as-09","teil":"IM1","g":"imas","th":"Brandschutz","n":1,"q":"Für welche Brände steht die Brandklasse B?","w":"A: feste Stoffe, B: flüssige Stoffe, C: Gase, D: Metalle, F: Speisefette und Speiseöle.","o":["Brände fester, glutbildender Stoffe, zum Beispiel Holz","Brände von Gasen","Brände flüssiger oder flüssig werdender Stoffe, zum Beispiel Öl und Lösemittel","Brände von Metallen"],"r":2},{"id":"IM-as-10","teil":"IM1","g":"imas","th":"Umweltschutz","n":1,"q":"Wie werden ölverschmutzte Putzlappen gesammelt?","w":"Ölgetränkte Lappen können sich selbst entzünden und sind gefährlicher Abfall. Sie werden getrennt gesammelt und fachgerecht entsorgt oder gewaschen.","o":["Im Papierkorb am Arbeitsplatz","Offen in einem Karton neben der Maschine","In gekennzeichneten, geschlossenen, nicht brennbaren Behältern","Zusammen mit den Metallspänen in der Spänewanne"],"r":2},{"id":"IM-as-11","teil":"IM1","g":"imas","th":"Umweltschutz","n":2,"q":"Welche Maßnahme hat in der Abfallhierarchie den höchsten Rang?","w":"Rangfolge: Vermeiden, zur Wiederverwendung vorbereiten, Recycling, sonstige Verwertung (zum Beispiel energetisch), Beseitigen.","o":["Abfall stofflich verwerten (Recycling)","Abfall verbrennen und die Wärme nutzen","Abfall auf einer Deponie beseitigen","Abfall vermeiden"],"r":3},{"id":"IM-as-12","teil":"IM1","g":"imas","th":"Elektrische Gefährdung","n":1,"q":"An der Anschlussleitung einer Handbohrmaschine ist die Isolierung beschädigt. Was ist zu tun?","w":"Beschädigte Leitungen sind lebensgefährlich. Reparaturen an elektrischen Betriebsmitteln führt nur die Elektrofachkraft aus.","o":["Maschine nicht mehr benutzen, kennzeichnen und einer Elektrofachkraft zur Reparatur geben","Schadstelle mit Isolierband umwickeln und weiterarbeiten","Nur noch mit Handschuhen weiterarbeiten","Weiterarbeiten, solange die Maschine läuft"],"r":0},{"id":"IM-as-13","teil":"IM1","g":"imas","th":"Not-Halt","n":1,"q":"Wie ist ein Not-Halt-Befehlsgerät gekennzeichnet?","w":"Der Not-Halt muss auffällig, schnell erreichbar und leicht zu betätigen sein. Er rastet ein und muss von Hand entriegelt werden.","o":["Grüner Drucktaster auf weißem Untergrund","Roter Pilztaster auf gelbem Untergrund","Gelber Pilztaster auf rotem Untergrund","Blauer Leuchttaster"],"r":1},{"id":"IM-as-14","teil":"IM1","g":"imas","th":"Heben und Tragen","n":1,"q":"Wie wird eine schwere Kiste richtig vom Boden gehoben?","w":"Die Kraft kommt aus den Beinen. Ein runder oder verdrehter Rücken belastet die Bandscheiben einseitig.","o":["Mit gestreckten Beinen und rundem Rücken","Mit Schwung und einer Drehung des Oberkörpers","Mit geradem Rücken aus der Hocke heben, Last nah am Körper","Mit ausgestreckten Armen weit vor dem Körper"],"r":2},{"id":"IM-as-15","teil":"IM1","g":"imas","th":"Maschinenarbeit","n":1,"q":"Wie werden Späne von einer Werkzeugmaschine entfernt?","w":"Späne sind scharf und heiß. Druckluft schleudert sie umher und treibt sie in Führungen. An drehende Teile wird nie hineingegriffen.","o":["Bei laufender Maschine mit der Hand","Mit Druckluft in Richtung des Nachbararbeitsplatzes","Mit einem Putzlappen bei laufender Spindel","Bei stehender Maschine mit Spänehaken oder Handfeger"],"r":3},{"id":"IM-as-16","teil":"IM1","g":"imas","th":"Schleifen","n":2,"q":"Was wird mit der Klangprobe vor dem Aufspannen einer Schleifscheibe geprüft?","w":"Eine unbeschädigte keramisch gebundene Scheibe klingt beim leichten Anschlagen hell. Ein dumpfer oder scheppernder Ton deutet auf Risse: Die Scheibe darf nicht verwendet werden.","o":["Ob die Schleifscheibe Risse hat","Ob die Körnung zur Aufgabe passt","Ob die Scheibe ausgewuchtet ist","Ob die Bohrung der Scheibe maßhaltig ist"],"r":0},{"id":"IM-st-01","teil":"IM1","g":"imst","th":"Wegeventile","n":1,"q":"Mit welchem Wegeventil wird ein einfachwirkender Zylinder direkt angesteuert?","w":"Das 3/2-Wegeventil belüftet den Zylinder in der einen und entlüftet ihn in der anderen Stellung. Die Feder im Zylinder stellt den Kolben zurück.","o":["2/2-Wegeventil ohne Entlüftung","5/3-Wegeventil mit gesperrter Mittelstellung","Rückschlagventil","3/2-Wegeventil"],"r":3},{"id":"IM-st-02","teil":"IM1","g":"imst","th":"Wegeventile","n":1,"q":"Mit welchem Wegeventil wird ein doppeltwirkender Zylinder üblicherweise angesteuert?","w":"Das 5/2-Wegeventil belüftet abwechselnd eine Kolbenseite und entlüftet die andere über einen eigenen Entlüftungsanschluss.","o":["5/2-Wegeventil","3/2-Wegeventil allein","2/2-Wegeventil allein","Wechselventil"],"r":0},{"id":"IM-st-03","teil":"IM1","g":"imst","th":"Geschwindigkeit","n":2,"q":"Wie wird die Geschwindigkeit eines doppeltwirkenden Zylinders üblicherweise eingestellt?","w":"Bei der Abluftdrosselung ist der Kolben zwischen zwei Luftpolstern eingespannt und fährt gleichmäßig. Das Rückschlagventil lässt die Zuluft ungedrosselt durch.","o":["Durch Drosseln der Zuluft vor der Wartungseinheit","Durch Abluftdrosselung mit Drosselrückschlagventilen","Durch Verändern der Federkraft im Wegeventil","Durch ein Wechselventil in der Zuleitung"],"r":1},{"id":"IM-st-04","teil":"IM1","g":"imst","th":"Logikventile","n":1,"q":"Ein Zylinder soll nur ausfahren, wenn zwei Taster gleichzeitig betätigt sind. Welches Ventil verknüpft die beiden Signale?","w":"Das Zweidruckventil gibt nur dann ein Ausgangssignal, wenn an beiden Eingängen Druck anliegt.","o":["Wechselventil (ODER)","Schnellentlüftungsventil","Zweidruckventil (UND)","Drosselrückschlagventil"],"r":2},{"id":"IM-st-05","teil":"IM1","g":"imst","th":"Logikventile","n":1,"q":"Ein Zylinder soll wahlweise von zwei verschiedenen Stellen aus gestartet werden. Welches Ventil verknüpft die beiden Signale?","w":"Das Wechselventil gibt ein Ausgangssignal, wenn an einem der beiden Eingänge Druck anliegt, und sperrt dabei den anderen Eingang.","o":["Zweidruckventil (UND)","Druckregelventil","Rückschlagventil","Wechselventil (ODER)"],"r":3},{"id":"IM-st-06","teil":"IM1","g":"imst","th":"Geschwindigkeit","n":2,"q":"Welche Aufgabe hat ein Schnellentlüftungsventil?","w":"Die Abluft muss nicht den langen Weg durch Leitung und Wegeventil nehmen. Das Ventil sitzt deshalb direkt am Zylinder.","o":["Es entlüftet den Zylinder direkt ins Freie und erhöht so die Kolbengeschwindigkeit","Es entlüftet die gesamte Anlage beim Betätigen des Not-Halts","Es begrenzt den Druck im Zylinder","Es verzögert das Einfahren des Zylinders"],"r":0},{"id":"IM-st-07","teil":"IM1","g":"imst","th":"Anschlussbezeichnungen","n":1,"q":"Was bezeichnet die Ziffer 1 an einem pneumatischen Wegeventil?","w":"1: Druckluft, 2 und 4: Arbeitsanschlüsse, 3 und 5: Entlüftungen, 12 und 14: Steueranschlüsse.","o":["Einen Arbeitsanschluss","Den Druckluftanschluss","Einen Entlüftungsanschluss","Einen Steueranschluss"],"r":1},{"id":"IM-st-08","teil":"IM1","g":"imst","th":"Steuern und Regeln","n":2,"q":"Was unterscheidet eine Steuerung von einer Regelung?","w":"Bei der Regelung wird die Regelgröße gemessen, mit dem Sollwert verglichen und nachgestellt (geschlossener Regelkreis). Die Steuerung gleicht Störungen nicht aus.","o":["Die Steuerung arbeitet immer pneumatisch, die Regelung immer elektrisch","Die Steuerung vergleicht ständig Istwert und Sollwert","Die Steuerung hat einen offenen Wirkungsablauf ohne Rückführung der Ausgangsgröße","Die Regelung kommt ohne Messglied aus"],"r":2},{"id":"IM-st-09","teil":"IM1","g":"imst","th":"Kolbenkraft","n":2,"q":"Ein Zylinder mit 50 mm Kolbendurchmesser wird mit 6 bar beaufschlagt. Wie groß ist die Kolbenkraft beim Ausfahren ohne Reibung?","w":"A = π · d² / 4 = 19,63 cm². 6 bar = 60 N/cm². F = p · A = 60 N/cm² · 19,63 cm² ≈ 1178 N.","o":["etwa 4712 N","etwa 300 N","etwa 118 N","etwa 1178 N"],"r":3},{"id":"IM-st-10","teil":"IM1","g":"imst","th":"Signalglieder","n":2,"q":"Welche Aufgabe hat ein 3/2-Wegeventil mit Rollenhebel an der vorderen Endlage eines Zylinders?","w":"Signalglieder erfassen Zustände und geben sie an die Steuerung weiter. Das Bremsen übernimmt die Endlagendämpfung im Zylinder.","o":["Es bremst den Kolben in der Endlage ab","Es stellt den Betriebsdruck des Zylinders ein","Es entlüftet den Zylinder schneller","Es meldet als Grenztaster, dass der Kolben ausgefahren ist"],"r":3},{"id":"IM-st-11","teil":"IM1","g":"imst","th":"Wegeventile","n":2,"q":"Ein 3/2-Wegeventil ist in Ruhestellung gesperrt. Was gilt in der Ruhestellung?","w":"In Ruhestellung gesperrt heißt: Unbetätigt gelangt keine Druckluft zum Verbraucher, der Arbeitsanschluss ist drucklos.","o":["Anschluss 1 ist mit 2 verbunden, 3 ist gesperrt","Alle drei Anschlüsse sind miteinander verbunden","Anschluss 1 ist gesperrt, der Arbeitsanschluss 2 ist über 3 entlüftet","Alle drei Anschlüsse sind gesperrt"],"r":2},{"id":"IM-st-12","teil":"IM1","g":"imst","th":"Ansteuerung","n":2,"q":"Was bedeutet indirekte Ansteuerung eines Zylinders?","w":"Die indirekte Ansteuerung wird bei großen Zylindern und langen Leitungen verwendet. Das Signalventil kann klein und leicht zu betätigen sein.","o":["Der Zylinder wird ohne Ventil direkt an die Druckluft angeschlossen","Ein kleines Signalventil schaltet mit Druckluft das Stellventil, das den Zylinder versorgt","Der Taster wirkt mechanisch auf den Kolben","Der Zylinder wird über zwei Drosseln angesteuert"],"r":1},{"id":"IM-st-N01","teil":"IM1","g":"imst","th":"Kolbenkraft","n":2,"q":"Ein Pneumatikzylinder mit 32 mm Kolbendurchmesser wird mit 6 bar beaufschlagt. Berechnen Sie die Kolbenkraft beim Ausfahren in N (ohne Reibung).","w":"A = π · (3,2 cm)² / 4 = 8,04 cm². F = 60 N/cm² · 8,04 cm² ≈ 483 N.","ans":482.5,"u":"N","tol":0.02},{"id":"IM-mt-01","teil":"IM1","g":"immt","th":"Dreisatz","n":1,"q":"4 gleiche Maschinen fertigen einen Auftrag in 15 Stunden. Wie lange brauchen 6 Maschinen für denselben Auftrag?","w":"Umgekehrtes Verhältnis: 4 · 15 h = 60 Maschinenstunden. 60 h / 6 = 10 h.","o":["22,5 Stunden","10 Stunden","9 Stunden","12 Stunden"],"r":1},{"id":"IM-mt-02","teil":"IM1","g":"immt","th":"Prozentrechnung","n":1,"q":"Von 800 gefertigten Teilen sind 24 Ausschuss. Wie hoch ist der Ausschussanteil?","w":"24 / 800 = 0,03 = 3 %.","o":["0,3 %","24 %","3 %","33 %"],"r":2},{"id":"IM-mt-03","teil":"IM1","g":"immt","th":"Pythagoras","n":2,"q":"Eine rechteckige Platte ist 60 mm breit und 80 mm lang. Wie lang ist die Diagonale?","w":"d = √(60² + 80²) mm = √10 000 mm = 100 mm.","o":["140 mm","70 mm","120 mm","100 mm"],"r":3},{"id":"IM-mt-04","teil":"IM1","g":"immt","th":"Winkelfunktionen","n":3,"q":"Eine Schräge steigt auf 50 mm waagerechter Länge um 20 mm an. Wie groß ist der Neigungswinkel?","w":"tan α = Gegenkathete / Ankathete = 20 / 50 = 0,4. α ≈ 21,8°. 23,6° ergibt sich fälschlich mit dem Sinus.","o":["etwa 21,8°","etwa 23,6°","etwa 66,4°","etwa 68,2°"],"r":0},{"id":"IM-mt-05","teil":"IM1","g":"immt","th":"Flächen","n":2,"q":"Eine Scheibe hat den Außendurchmesser 60 mm und eine Bohrung mit 40 mm Durchmesser. Wie groß ist die Kreisringfläche?","w":"A = π / 4 · (D² - d²) = π / 4 · (3600 - 1600) mm² ≈ 1571 mm².","o":["etwa 314 mm²","etwa 1571 mm²","etwa 6283 mm²","etwa 2827 mm²"],"r":1},{"id":"IM-mt-06","teil":"IM1","g":"immt","th":"Volumen und Masse","n":2,"q":"Welche Masse hat ein Rundstahl mit 40 mm Durchmesser und 500 mm Länge (Dichte 7,85 kg/dm³)?","w":"V = π / 4 · (0,4 dm)² · 5 dm = 0,628 dm³. m = V · ρ = 0,628 dm³ · 7,85 kg/dm³ ≈ 4,93 kg.","o":["etwa 19,7 kg","etwa 0,49 kg","etwa 4,93 kg","etwa 6,28 kg"],"r":2},{"id":"IM-mt-07","teil":"IM1","g":"immt","th":"Einheiten","n":1,"q":"Wie groß ist ein Druck von 8 bar in N/mm²?","w":"1 bar = 10 N/cm² = 0,1 N/mm². 8 bar = 0,8 N/mm².","o":["8 N/mm²","80 N/mm²","0,08 N/mm²","0,8 N/mm²"],"r":3},{"id":"IM-mt-08","teil":"IM1","g":"immt","th":"Hebel","n":2,"q":"An einem zweiseitigen Hebel wirkt F1 = 200 N am Hebelarm 600 mm. Welche Kraft F2 hält am Hebelarm 150 mm das Gleichgewicht?","w":"F1 · l1 = F2 · l2. F2 = 200 N · 600 mm / 150 mm = 800 N.","o":["800 N","50 N","400 N","1200 N"],"r":0},{"id":"IM-mt-09","teil":"IM1","g":"immt","th":"Leistung","n":2,"q":"Ein Hubwerk hebt eine Last mit der Gewichtskraft 2000 N in 6 s um 3 m. Welche Hubleistung ist dazu nötig?","w":"W = F · s = 2000 N · 3 m = 6000 N·m. P = W / t = 6000 N·m / 6 s = 1000 W.","o":["4000 W","1000 W","333 W","36 000 W"],"r":1},{"id":"IM-mt-10","teil":"IM1","g":"immt","th":"Wirkungsgrad","n":1,"q":"Ein Getriebemotor nimmt 4 kW auf und gibt 3,4 kW ab. Wie groß ist der Wirkungsgrad?","w":"η = Pab / Pzu = 3,4 kW / 4 kW = 0,85 = 85 %. Der Wirkungsgrad ist immer kleiner als 100 %.","o":["118 %","85 %","60 %","15 %"],"r":1},{"id":"IM-mt-11","teil":"IM1","g":"immt","th":"Gestreckte Länge","n":3,"q":"Ein Blech wird um 90° gebogen. Der Radius der neutralen Faser beträgt 12 mm. Wie lang ist der Bogen der neutralen Faser?","w":"Ein Viertelkreis: l = π · r / 2 = π · 12 mm / 2 ≈ 18,8 mm.","o":["etwa 18,8 mm","etwa 37,7 mm","etwa 75,4 mm","etwa 9,4 mm"],"r":0},{"id":"IM-mt-12","teil":"IM1","g":"immt","th":"Flächenpressung","n":2,"q":"Eine Kraft von 12 kN wirkt auf eine Auflagefläche von 40 mm x 30 mm. Wie groß ist die Flächenpressung?","w":"p = F / A = 12 000 N / (40 mm · 30 mm) = 12 000 N / 1200 mm² = 10 N/mm².","o":["100 N/mm²","1 N/mm²","171 N/mm²","10 N/mm²"],"r":3},{"id":"IM-mt-N01","teil":"IM1","g":"immt","th":"Volumen und Masse","n":2,"q":"Ein Flachstahl 100 mm x 20 mm ist 400 mm lang (Dichte 7,85 kg/dm³). Berechnen Sie die Masse in kg.","w":"V = 1 dm · 0,2 dm · 4 dm = 0,8 dm³. m = 0,8 dm³ · 7,85 kg/dm³ = 6,28 kg.","ans":6.28,"u":"kg","tol":0.02},{"id":"IM-mt-N02","teil":"IM1","g":"immt","th":"Pythagoras","n":2,"q":"Zwei Bohrungen liegen in x-Richtung 50 mm und in y-Richtung 120 mm auseinander. Berechnen Sie den Mittenabstand in mm.","w":"a = √(50² + 120²) mm = √16 900 mm = 130 mm.","ans":130,"u":"mm","tol":0.02},{"id":"IM-mt-N03","teil":"IM1","g":"immt","th":"Prozentrechnung","n":1,"q":"Von 600 gefertigten Teilen sind 18 Ausschuss. Berechnen Sie den Ausschussanteil in Prozent.","w":"18 / 600 = 0,03 = 3 %.","ans":3,"u":"%","tol":0.02},{"id":"IM-mt-N04","teil":"IM1","g":"immt","th":"Hebel","n":2,"q":"An einem zweiseitigen Hebel wirkt F1 = 150 N am Hebelarm 800 mm. Berechnen Sie die Kraft F2 in N, die am Hebelarm 200 mm das Gleichgewicht hält.","w":"F2 = F1 · l1 / l2 = 150 N · 800 mm / 200 mm = 600 N.","ans":600,"u":"N","tol":0.02},{"id":"IM-me-01","teil":"IMA","g":"imme","th":"Lager","n":2,"q":"Welchen Vorteil haben Wälzlager gegenüber Gleitlagern?","w":"Wälzlager haben ein kleines Anlaufreibmoment und sind genormt austauschbar. Gleitlager dämpfen besser und laufen leiser, Wälzlager sind stoß- und schmutzempfindlich.","o":["Geringe Reibung beim Anlauf und wenig Schmierstoffbedarf","Sie dämpfen Stöße und Schwingungen besser","Sie laufen grundsätzlich geräuschärmer","Sie sind unempfindlich gegen Schmutz"],"r":0},{"id":"IM-me-02","teil":"IMA","g":"imme","th":"Lager","n":2,"q":"Welche Kräfte kann ein Rillenkugellager aufnehmen?","w":"Das Rillenkugellager ist das am häufigsten verwendete Wälzlager. Es eignet sich für hohe Drehzahlen und führt die Welle auch axial.","o":["Nur Axialkräfte","Nur Radialkräfte, Axialkräfte zerstören es sofort","Hohe Axialkräfte, aber nur in einer Richtung","Radialkräfte und kleinere Axialkräfte in beiden Richtungen"],"r":3},{"id":"IM-me-03","teil":"IMA","g":"imme","th":"Lager","n":2,"q":"Warum werden Kegelrollenlager meist paarweise und gegeneinander angestellt eingebaut?","w":"Kegelrollenlager tragen hohe Radial- und einseitige Axialkräfte. Das zweite, spiegelbildlich eingebaute Lager übernimmt die Gegenrichtung, das Lagerspiel wird beim Einbau eingestellt.","o":["Ein einzelnes Lager kann keine Radialkräfte aufnehmen","Sie laufen sonst zu schnell","Ein einzelnes Lager nimmt Axialkräfte nur in einer Richtung auf","Sie brauchen sonst keinen Schmierstoff"],"r":2},{"id":"IM-me-04","teil":"IMA","g":"imme","th":"Lager","n":1,"q":"Welches Lager nimmt ausschließlich Axialkräfte auf?","w":"Beim Axial-Rillenkugellager laufen die Kugeln zwischen zwei Scheiben. Radialkräfte kann es nicht aufnehmen.","o":["Nadellager","Axial-Rillenkugellager","Zylinderrollenlager mit bordlosem Außenring","Pendelkugellager"],"r":1},{"id":"IM-me-05","teil":"IMA","g":"imme","th":"Lager","n":1,"q":"Welche Eigenschaft hat ein Nadellager?","w":"Die dünnen, langen Wälzkörper brauchen wenig Platz. Axialkräfte und Schiefstellungen verträgt das Nadellager nicht.","o":["Sehr kleine radiale Bauhöhe bei hoher radialer Tragfähigkeit","Es nimmt hohe Axialkräfte auf","Es gleicht große Fluchtungsfehler aus","Es braucht keine gehärtete Lauffläche"],"r":0},{"id":"IM-me-06","teil":"IMA","g":"imme","th":"Lageranordnung","n":2,"q":"Welche Aufgabe hat das Loslager einer Fest-Los-Lagerung?","w":"Das Festlager führt die Welle axial. Das Loslager trägt nur radial und kann sich axial verschieben, sonst würden sich die Lager bei Wärmedehnung verspannen.","o":["Es führt die Welle axial in beiden Richtungen","Es überträgt das Drehmoment auf das Gehäuse","Es dichtet das Gehäuse ab","Es lässt Längenänderungen der Welle durch Erwärmung zu"],"r":3},{"id":"IM-me-07","teil":"IMA","g":"imme","th":"Lagerbezeichnung","n":2,"q":"Bei Wälzlagern ergibt die Bohrungskennzahl ab 04 mit 5 multipliziert den Bohrungsdurchmesser in mm. Welchen Bohrungsdurchmesser hat das Lager 6206?","w":"Die letzten beiden Ziffern sind die Bohrungskennzahl: 06 · 5 = 30 mm.","o":["6 mm","62 mm","30 mm","206 mm"],"r":2},{"id":"IM-me-08","teil":"IMA","g":"imme","th":"Lagersitze","n":3,"q":"Eine Welle läuft um, die Last wirkt immer in dieselbe Richtung (Umfangslast am Innenring). Wie werden die Lagerringe gepasst?","w":"Der Ring mit Umfangslast braucht einen festen Sitz, sonst wandert er und der Sitz schlägt aus. Der Ring mit Punktlast kann lose gepasst werden.","o":["Innenring lose auf der Welle, Außenring fest im Gehäuse","Innenring mit festem Sitz auf der Welle, Außenring darf lose im Gehäuse sitzen","Beide Ringe grundsätzlich lose","Beide Ringe werden verklebt, die Passung ist unwichtig"],"r":1},{"id":"IM-me-09","teil":"IMA","g":"imme","th":"Lagermontage","n":2,"q":"Ein Rillenkugellager wird auf eine Welle gepresst. Wo muss die Montagekraft angreifen?","w":"Die Kraft wird immer über den Ring geleitet, der gefügt wird. Sonst läuft sie über die Wälzkörper und beschädigt die Laufbahnen.","o":["Am Innenring","Am Außenring","Am Käfig","An den Dichtscheiben"],"r":0},{"id":"IM-me-10","teil":"IMA","g":"imme","th":"Lagermontage","n":2,"q":"Wie wird ein größeres Wälzlager für die Montage auf einer Welle mit festem Sitz vorbereitet?","w":"Durch die Erwärmung weitet sich der Innenring und lässt sich aufschieben. Zu hohe Temperaturen oder eine offene Flamme verändern das Gefüge und zerstören das Lager.","o":["Gleichmäßig auf etwa 80 °C bis 100 °C erwärmen, zum Beispiel mit einem Induktionsgerät","Mit dem Schweißbrenner auf Rotglut erwärmen","Das Lager in flüssigem Stickstoff abkühlen","Die Laufbahnen entfetten und trocken aufschlagen"],"r":0},{"id":"IM-me-11","teil":"IMA","g":"imme","th":"Wellen und Achsen","n":1,"q":"Worin unterscheiden sich Wellen und Achsen?","w":"Wellen werden auf Verdrehung (Torsion) und meist zusätzlich auf Biegung beansprucht. Achsen können feststehen oder umlaufen.","o":["Wellen stehen immer still, Achsen drehen sich immer","Wellen übertragen ein Drehmoment, Achsen tragen nur und werden auf Biegung beansprucht","Achsen übertragen ein Drehmoment, Wellen nicht","Wellen sind immer hohl, Achsen immer voll"],"r":1},{"id":"IM-me-12","teil":"IMA","g":"imme","th":"Welle-Nabe-Verbindung","n":1,"q":"Wie überträgt eine Passfederverbindung das Drehmoment?","w":"Die Flanken der Passfeder tragen. Zwischen Passfederrücken und Nabennut ist Spiel. Die Nabe muss zusätzlich axial gesichert werden.","o":["Kraftschlüssig durch Verspannen von Welle und Nabe","Stoffschlüssig durch die Passung","Formschlüssig über die Seitenflächen der Passfeder","Über die Rückenfläche der Passfeder, die an der Nabe anliegt"],"r":2},{"id":"IM-me-13","teil":"IMA","g":"imme","th":"Welle-Nabe-Verbindung","n":2,"q":"Wie wird ein Querpressverband (Schrumpfverbindung) gefügt?","w":"Die erwärmte Nabe dehnt sich aus. Nach dem Abkühlen sitzt sie mit Übermaß und überträgt das Drehmoment kraftschlüssig durch Reibung.","o":["Die Welle wird erwärmt und in die Nabe geschoben","Welle und Nabe werden mit einer Passfeder verbunden","Die Nabe wird auf die Welle geschraubt","Die Nabe wird erwärmt und auf die Welle geschoben, beim Abkühlen entsteht die Pressung"],"r":3},{"id":"IM-me-14","teil":"IMA","g":"imme","th":"Wellen und Achsen","n":2,"q":"Warum erhalten Wellenabsätze eine Ausrundung oder einen Freistich?","w":"An scharfkantigen Querschnittsübergängen entstehen Spannungsspitzen. Dort beginnen bei wechselnder Belastung Dauerbrüche.","o":["Die Kerbwirkung und damit die Gefahr eines Dauerbruchs wird verringert","Die Welle wird dadurch leichter","Der Schmierstoff kann besser abfließen","Die Welle lässt sich dann schneller drehen"],"r":0},{"id":"IM-me-15","teil":"IMA","g":"imme","th":"Sicherungselemente","n":1,"q":"Welche Aufgabe hat ein Sicherungsring in einer Wellennut?","w":"Sicherungsringe sind formschlüssige Axialsicherungen. Sie werden mit einer passenden Zange montiert.","o":["Er überträgt das Drehmoment von der Welle auf die Nabe","Er sichert Bauteile wie Lager oder Zahnräder gegen axiales Verschieben","Er dichtet die Welle gegen Ölaustritt ab","Er gleicht Unwucht aus"],"r":1},{"id":"IM-me-16","teil":"IMA","g":"imme","th":"Zahnräder","n":2,"q":"Ein Stirnrad hat 40 Zähne und den Teilkreisdurchmesser 100 mm. Wie groß ist der Modul?","w":"m = d / z = 100 mm / 40 = 2,5 mm.","o":["4 mm","0,4 mm","2,5 mm","60 mm"],"r":2},{"id":"IM-me-17","teil":"IMA","g":"imme","th":"Zahnräder","n":2,"q":"Wie groß ist der Teilkreisdurchmesser eines Stirnrads mit Modul 3 mm und 24 Zähnen?","w":"d = m · z = 3 mm · 24 = 72 mm. 78 mm wäre der Kopfkreisdurchmesser.","o":["8 mm","78 mm","27 mm","72 mm"],"r":3},{"id":"IM-me-18","teil":"IMA","g":"imme","th":"Zahnräder","n":2,"q":"Welche Besonderheit haben schrägverzahnte Stirnräder gegenüber geradverzahnten?","w":"Bei der Schrägverzahnung sind mehrere Zähne gleichzeitig im Eingriff. Die Axialkraft muss von den Lagern aufgenommen werden.","o":["Sie laufen ruhiger, erzeugen aber Axialkräfte","Sie laufen lauter, erzeugen aber keine Lagerkräfte","Sie lassen sich nur mit Riemen kombinieren","Sie brauchen keinen Schmierstoff"],"r":0},{"id":"IM-me-19","teil":"IMA","g":"imme","th":"Zahnräder","n":2,"q":"Wie groß ist der Kopfkreisdurchmesser eines Stirnrads mit Modul 2 mm und 30 Zähnen (Kopfhöhe = Modul)?","w":"da = d + 2 · m = m · (z + 2) = 2 mm · 32 = 64 mm.","o":["60 mm","64 mm","62 mm","55 mm"],"r":1},{"id":"IM-me-20","teil":"IMA","g":"imme","th":"Riementriebe","n":1,"q":"Welcher Riementrieb arbeitet schlupffrei?","w":"Der Zahnriemen überträgt die Bewegung formschlüssig und damit synchron. Flach-, Keil- und Rundriemen arbeiten kraftschlüssig mit Dehnschlupf.","o":["Flachriementrieb","Keilriementrieb","Rundriementrieb","Zahnriementrieb"],"r":3},{"id":"IM-me-21","teil":"IMA","g":"imme","th":"Riementriebe","n":2,"q":"Wie liegt ein Keilriemen richtig in der Riemenscheibe?","w":"Die Keilwirkung der Flanken erzeugt die hohe Reibkraft. Liegt der Riemen am Grund auf, ist er verschlissen oder passt nicht zum Profil.","o":["Er liegt auf dem Rillengrund auf, die Flanken haben Spiel","Er ragt weit über den Scheibenrand hinaus","Er trägt an den Flanken und berührt den Rillengrund nicht","Er liegt verdreht in der Rille, damit er sich spannt"],"r":2},{"id":"IM-me-22","teil":"IMA","g":"imme","th":"Kettentriebe","n":2,"q":"Welchen Vorteil hat ein Kettentrieb gegenüber einem Flachriementrieb?","w":"Die Kette greift formschlüssig in die Kettenräder. Sie muss geschmiert werden und läuft lauter als ein Riemen.","o":["Er läuft ohne Schmierung und geräuschlos","Schlupffreie Übertragung bei geringer Lagerbelastung, weil keine hohe Vorspannung nötig ist","Er dämpft Stöße elastisch","Er eignet sich für sehr hohe Umfangsgeschwindigkeiten"],"r":1},{"id":"IM-me-23","teil":"IMA","g":"imme","th":"Kettentriebe","n":3,"q":"Eine Rollenkette hat sich durch Gelenkverschleiß deutlich gelängt. Was ist zu tun?","w":"Eine gelängte Kette passt nicht mehr zur Teilung der Räder und steigt an den Zähnen auf. Eine neue Kette auf eingelaufenen Rädern verschleißt schnell.","o":["Kette und Kettenräder gemeinsam ersetzen","Nur die Kette nachspannen, bis kein Durchhang mehr vorhanden ist","Ein Kettenglied entfernen und die Kette weiterverwenden","Die Kette umdrehen und wieder auflegen"],"r":0},{"id":"IM-me-24","teil":"IMA","g":"imme","th":"Kupplungen","n":2,"q":"Welche Eigenschaft hat eine elastische Klauenkupplung mit Zahnkranz aus Kunststoff?","w":"Der elastische Zahnkranz nimmt Stöße auf und verträgt kleine Fluchtungsfehler. Starre Kupplungen verlangen genau fluchtende Wellen.","o":["Sie lässt sich während des Betriebs ein- und ausschalten","Sie verlangt exakt fluchtende Wellen und überträgt Stöße ungedämpft","Sie begrenzt das Drehmoment durch Rutschen","Sie dämpft Drehmomentstöße und gleicht kleine Wellenversätze aus"],"r":3},{"id":"IM-me-25","teil":"IMA","g":"imme","th":"Kupplungen","n":2,"q":"Welche Kupplung lässt sich unter Last und bei Drehzahl schalten?","w":"Reibkupplungen gleichen beim Einschalten die Drehzahlen durch Rutschen an. Formschlüssige Klauenkupplungen werden nur im Stillstand oder bei Gleichlauf geschaltet.","o":["Klauenschaltkupplung","Scheibenkupplung","Lamellenkupplung (Reibkupplung)","Schalenkupplung"],"r":2},{"id":"IM-me-26","teil":"IMA","g":"imme","th":"Kupplungen","n":2,"q":"Welche Aufgabe hat eine Rutschkupplung in einem Antrieb?","w":"Wird das eingestellte Drehmoment überschritten, rutscht die Kupplung durch. So werden Getriebe und Wellen bei einer Blockade nicht zerstört.","o":["Sie erhöht das Drehmoment beim Anfahren","Sie begrenzt das Drehmoment und schützt den Antrieb vor Überlast","Sie gleicht große Winkelversätze aus","Sie verbindet zwei Wellen starr und spielfrei"],"r":1},{"id":"IM-me-27","teil":"IMA","g":"imme","th":"Dichtungen","n":2,"q":"Wie wird ein Radialwellendichtring eingebaut, der ein Getriebe gegen Ölaustritt abdichtet?","w":"Der Öldruck und die Schlauchfeder drücken die Dichtlippe auf die Welle. Die Lauffläche der Welle muss glatt und drallfrei sein.","o":["Die Dichtlippe zeigt zur Ölseite","Die Dichtlippe zeigt nach außen zur Luftseite","Die Einbaurichtung ist beliebig","Die Dichtlippe wird vor dem Einbau abgeschnitten"],"r":0},{"id":"IM-me-28","teil":"IMA","g":"imme","th":"Dichtungen","n":2,"q":"Welche Dichtung arbeitet berührungsfrei?","w":"Die Labyrinthdichtung dichtet über enge, verwinkelte Spalte. Sie verschleißt nicht und eignet sich für hohe Drehzahlen.","o":["Radialwellendichtring","O-Ring","Stopfbuchspackung","Labyrinthdichtung"],"r":3},{"id":"IM-me-29","teil":"IMA","g":"imme","th":"Federn","n":2,"q":"Eine Druckfeder wird mit 600 N belastet und federt dabei 12 mm ein. Wie groß ist die Federrate?","w":"R = F / s = 600 N / 12 mm = 50 N/mm.","o":["7200 N/mm","0,02 N/mm","50 N/mm","588 N/mm"],"r":2},{"id":"IM-me-30","teil":"IMA","g":"imme","th":"Gleitlager","n":2,"q":"Warum bestehen Gleitlagerbuchsen häufig aus Bronze oder einem anderen weicheren Lagerwerkstoff?","w":"Die teure Welle soll nicht verschleißen. Der weichere Lagerwerkstoff bettet Schmutzteilchen ein und frisst bei Mangelschmierung nicht sofort.","o":["Der Lagerwerkstoff soll härter als die Welle sein","Bronze ist magnetisch und hält das Öl fest","Der Lagerwerkstoff hat gute Gleit- und Notlaufeigenschaften und schont die Welle","Bronze dehnt sich bei Erwärmung nicht aus"],"r":2},{"id":"IM-me-N01","teil":"IMA","g":"imme","th":"Zahnräder","n":1,"q":"Ein Stirnrad hat den Modul 4 mm und 35 Zähne. Berechnen Sie den Teilkreisdurchmesser in mm.","w":"d = m · z = 4 mm · 35 = 140 mm.","ans":140,"u":"mm","tol":0.02},{"id":"IM-me-N02","teil":"IMA","g":"imme","th":"Zahnräder","n":2,"q":"Zwei Stirnräder mit dem Modul 3 mm haben 18 und 42 Zähne. Berechnen Sie den Achsabstand in mm.","w":"a = m · (z1 + z2) / 2 = 3 mm · 60 / 2 = 90 mm.","ans":90,"u":"mm","tol":0.02},{"id":"IM-gt-01","teil":"IMA","g":"imgt","th":"Übersetzung","n":1,"q":"Das treibende Zahnrad hat 18 Zähne, das getriebene 54 Zähne. Wie groß ist das Übersetzungsverhältnis?","w":"i = z2 / z1 = 54 / 18 = 3 (Übersetzung ins Langsame).","o":["i = 0,33","i = 36","i = 72","i = 3"],"r":3},{"id":"IM-gt-02","teil":"IMA","g":"imgt","th":"Übersetzung","n":1,"q":"Ein Motor dreht mit 1440 1/min, das Getriebe hat die Übersetzung i = 4. Wie groß ist die Abtriebsdrehzahl?","w":"n2 = n1 / i = 1440 1/min / 4 = 360 1/min.","o":["360 1/min","5760 1/min","1436 1/min","36 1/min"],"r":0},{"id":"IM-gt-03","teil":"IMA","g":"imgt","th":"Mehrstufige Getriebe","n":2,"q":"Ein zweistufiges Getriebe hat die Stufenübersetzungen i1 = 3 und i2 = 4. Die Antriebsdrehzahl beträgt 1440 1/min. Wie groß ist die Abtriebsdrehzahl?","w":"Gesamtübersetzung i = i1 · i2 = 12. n2 = 1440 1/min / 12 = 120 1/min. Die Einzelübersetzungen werden multipliziert, nicht addiert.","o":["206 1/min","120 1/min","480 1/min","360 1/min"],"r":1},{"id":"IM-gt-04","teil":"IMA","g":"imgt","th":"Drehmoment","n":2,"q":"Ein Getriebe mit i = 5 und dem Wirkungsgrad 0,9 wird mit 20 N·m angetrieben. Wie groß ist das Abtriebsdrehmoment?","w":"M2 = M1 · i · η = 20 N·m · 5 · 0,9 = 90 N·m.","o":["100 N·m","4 N·m","90 N·m","111 N·m"],"r":2},{"id":"IM-gt-05","teil":"IMA","g":"imgt","th":"Riementrieb","n":2,"q":"Die treibende Riemenscheibe hat 100 mm Durchmesser und dreht mit 1400 1/min. Die getriebene Scheibe hat 280 mm Durchmesser. Wie schnell dreht sie (ohne Schlupf)?","w":"n1 · d1 = n2 · d2. n2 = 1400 1/min · 100 mm / 280 mm = 500 1/min.","o":["3920 1/min","1220 1/min","5 1/min","500 1/min"],"r":3},{"id":"IM-gt-06","teil":"IMA","g":"imgt","th":"Übersetzung","n":2,"q":"Was gilt für ein Getriebe mit dem Übersetzungsverhältnis i größer als 1?","w":"i größer als 1 ist eine Übersetzung ins Langsame. Die Leistung bleibt bis auf die Verluste gleich, deshalb steigt das Drehmoment.","o":["Die Abtriebsdrehzahl ist kleiner, das Abtriebsdrehmoment größer als am Antrieb","Die Abtriebsdrehzahl ist größer, das Abtriebsdrehmoment kleiner als am Antrieb","Drehzahl und Drehmoment steigen beide","Drehzahl und Drehmoment bleiben gleich, nur die Drehrichtung ändert sich"],"r":0},{"id":"IM-gt-07","teil":"IMA","g":"imgt","th":"Getriebearten","n":2,"q":"Welche Eigenschaft hat ein Schneckengetriebe?","w":"Schnecke und Schneckenrad gleiten stark aufeinander. Das ergibt große Übersetzungen, aber einen niedrigeren Wirkungsgrad und mehr Wärme.","o":["Sehr hoher Wirkungsgrad bei parallelen Achsen","Große Übersetzung in einer Stufe bei sich kreuzenden Achsen, oft selbsthemmend","Übersetzung immer ins Schnelle","Stufenlos verstellbare Übersetzung"],"r":1},{"id":"IM-gt-08","teil":"IMA","g":"imgt","th":"Getriebearten","n":1,"q":"Mit welchem Zahnradgetriebe wird die Drehbewegung zwischen zwei Wellen übertragen, deren Achsen sich schneiden (meist unter 90°)?","w":"Kegelräder haben kegelige Grundkörper, deren Achsen sich in einem Punkt schneiden. Stirnräder arbeiten auf parallelen Wellen.","o":["Stirnradgetriebe","Zahnstangengetriebe","Kegelradgetriebe","Planetengetriebe"],"r":2},{"id":"IM-gt-09","teil":"IMA","g":"imgt","th":"Zwischenrad","n":2,"q":"Zwischen ein treibendes und ein getriebenes Stirnrad wird ein Zwischenrad gesetzt. Was ändert sich?","w":"Die Zähnezahl des Zwischenrads kürzt sich heraus. Es überbrückt den Achsabstand und kehrt die Drehrichtung um.","o":["Die Gesamtübersetzung verdoppelt sich","Die Abtriebsdrehzahl halbiert sich","Es ändert sich nur der Modul","Die Drehrichtung des getriebenen Rads, die Gesamtübersetzung bleibt gleich"],"r":3},{"id":"IM-gt-10","teil":"IMA","g":"imgt","th":"Achsabstand","n":2,"q":"Zwei Stirnräder mit Modul 2 mm haben 20 und 60 Zähne. Wie groß ist der Achsabstand?","w":"a = m · (z1 + z2) / 2 = 2 mm · 80 / 2 = 80 mm.","o":["160 mm","40 mm","120 mm","80 mm"],"r":3},{"id":"IM-gt-11","teil":"IMA","g":"imgt","th":"Zahnstange","n":3,"q":"Ein Ritzel mit Modul 2 mm und 20 Zähnen treibt eine Zahnstange. Welchen Weg legt die Zahnstange bei einer Ritzelumdrehung zurück?","w":"Der Weg entspricht dem Teilkreisumfang: s = π · m · z = π · 2 mm · 20 ≈ 125,7 mm.","o":["40 mm","etwa 62,8 mm","etwa 125,7 mm","etwa 251,3 mm"],"r":2},{"id":"IM-gt-12","teil":"IMA","g":"imgt","th":"Gewindespindel","n":2,"q":"Eine Gewindespindel mit 5 mm Steigung dreht mit 120 1/min. Mit welcher Geschwindigkeit bewegt sich die Spindelmutter?","w":"v = P · n = 5 mm · 120 1/min = 600 mm/min.","o":["24 mm/min","600 mm/min","125 mm/min","6000 mm/min"],"r":1},{"id":"IM-gt-13","teil":"IMA","g":"imgt","th":"Leistung und Drehmoment","n":3,"q":"Eine Welle überträgt 50 N·m bei 955 1/min. Welche Leistung ist das (P in kW = M in N·m · n in 1/min / 9550)?","w":"P = 50 · 955 / 9550 kW = 5 kW.","o":["5 kW","47,8 kW","0,5 kW","19,1 kW"],"r":0},{"id":"IM-gt-N01","teil":"IMA","g":"imgt","th":"Übersetzung","n":1,"q":"Das treibende Zahnrad hat 24 Zähne und dreht mit 960 1/min, das getriebene Rad hat 72 Zähne. Berechnen Sie die Abtriebsdrehzahl in 1/min.","w":"i = 72 / 24 = 3. n2 = 960 1/min / 3 = 320 1/min.","ans":320,"u":"1/min","tol":0.02},{"id":"IM-gt-N02","teil":"IMA","g":"imgt","th":"Riementrieb","n":2,"q":"Die treibende Riemenscheibe (Ø90 mm) dreht mit 1450 1/min, die getriebene Scheibe hat Ø225 mm. Berechnen Sie die Abtriebsdrehzahl in 1/min (ohne Schlupf).","w":"n2 = n1 · d1 / d2 = 1450 1/min · 90 mm / 225 mm = 580 1/min.","ans":580,"u":"1/min","tol":0.02},{"id":"IM-gt-N03","teil":"IMA","g":"imgt","th":"Drehmoment","n":2,"q":"Ein Getriebe mit der Übersetzung i = 8 und dem Wirkungsgrad 0,85 wird mit 12 N·m angetrieben. Berechnen Sie das Abtriebsdrehmoment in N·m.","w":"M2 = M1 · i · η = 12 N·m · 8 · 0,85 = 81,6 N·m.","ans":81.6,"u":"N·m","tol":0.02},{"id":"IM-ph-01","teil":"IMA","g":"imph","th":"Schaltplanaufbau","n":1,"q":"Wie sind die Bauteile in einem pneumatischen Schaltplan angeordnet?","w":"Der Schaltplan zeigt die Funktion, nicht die Einbaulage. Die Druckluftversorgung steht unten, die Zylinder stehen oben.","o":["In Richtung des Energieflusses von unten nach oben: Versorgung, Signalglieder, Steuerglieder, Stellglieder, Antriebe","So, wie sie räumlich in der Maschine eingebaut sind","Von oben nach unten: Versorgung oben, Antriebe unten","Alphabetisch nach der Bauteilbezeichnung"],"r":0},{"id":"IM-ph-02","teil":"IMA","g":"imph","th":"Bauteilbezeichnung","n":2,"q":"Was bezeichnet die Kennzeichnung 1A1 in einem fluidtechnischen Schaltplan?","w":"Der Buchstabe nennt die Bauteilart: A Antrieb, V Ventil, S Signalaufnehmer, P Pumpe oder Verdichter, Z sonstige Bauteile. Davor steht die Nummer des Schaltkreises, dahinter die laufende Nummer.","o":["Ein Ventil im Schaltkreis 1","Einen Signalgeber im Schaltkreis 1","Die Druckluftquelle der Anlage","Ein Antriebsglied (zum Beispiel einen Zylinder) im Schaltkreis 1"],"r":3},{"id":"IM-ph-03","teil":"IMA","g":"imph","th":"Schaltplanaufbau","n":1,"q":"In welcher Stellung werden Ventile im Schaltplan gezeichnet?","w":"Ausgangsstellung heißt: Energie eingeschaltet, Anlage startbereit. Ist ein Ventil in dieser Stellung betätigt, wird das am Symbol gekennzeichnet.","o":["Immer in betätigter Stellung","In der Stellung, die sie beim letzten Betrieb hatten","In der Ausgangsstellung der Anlage, die Leitungen sind am Feld dieser Stellung angeschlossen","In einer beliebigen Stellung, das wird im Text erklärt"],"r":2},{"id":"IM-ph-04","teil":"IMA","g":"imph","th":"Funktionsdiagramm","n":2,"q":"Zwei Zylinder arbeiten im Ablauf A+ B+ B- A- (+ ausfahren, - einfahren). In welchem Schritt fährt Zylinder B ein?","w":"Schritt 1: A fährt aus, Schritt 2: B fährt aus, Schritt 3: B fährt ein, Schritt 4: A fährt ein.","o":["Im Schritt 1","Im Schritt 3","Im Schritt 2","Im Schritt 4"],"r":1},{"id":"IM-ph-05","teil":"IMA","g":"imph","th":"Signalüberschneidung","n":3,"q":"Was versteht man in einer pneumatischen Ablaufsteuerung unter einer Signalüberschneidung?","w":"Steht das alte Signal noch an, bleibt das Gegensignal wirkungslos. Abhilfe schaffen zum Beispiel Kipprollenventile, Umschaltventile oder Taktstufen.","o":["An beiden Steueranschlüssen eines Impulsventils liegt gleichzeitig ein Signal an, das Ventil kann nicht umschalten","Zwei Zylinder fahren gleichzeitig aus","Zwei Leitungen kreuzen sich im Schaltplan","Ein Signal kommt wegen einer langen Leitung verspätet an"],"r":0},{"id":"IM-ph-06","teil":"IMA","g":"imph","th":"Wegeventile","n":2,"q":"Welche Eigenschaft hat ein beidseitig druckluftbetätigtes 5/2-Wegeventil (Impulsventil)?","w":"Das Impulsventil hat Speicherverhalten. Ein kurzer Signalimpuls genügt zum Umschalten.","o":["Es fällt ohne Signal durch eine Feder in die Ruhestellung zurück","Es hat eine gesperrte Mittelstellung","Es schaltet nur, solange das Signal ansteht","Es behält seine Schaltstellung, bis ein Gegensignal kommt"],"r":3},{"id":"IM-ph-07","teil":"IMA","g":"imph","th":"Zeitverhalten","n":2,"q":"Aus welchen Teilen besteht ein pneumatisches Verzögerungsventil?","w":"Über die Drossel füllt sich der Speicher langsam. Erst wenn der Druck dort hoch genug ist, schaltet das 3/2-Wegeventil.","o":["Zwei Wechselventile und ein Schalldämpfer","Druckregelventil und Manometer","Drosselrückschlagventil, kleiner Luftspeicher und 3/2-Wegeventil","Zweidruckventil und Schnellentlüftungsventil"],"r":2},{"id":"IM-ph-08","teil":"IMA","g":"imph","th":"Druckventile","n":2,"q":"Ein Werkstück wird pneumatisch gespannt. Der Bearbeitungszylinder soll erst starten, wenn der Spanndruck erreicht ist. Welches Bauteil gibt das Signal?","w":"Das Druckschaltventil schaltet, wenn am Steueranschluss der eingestellte Druck erreicht ist. So wird druckabhängig weitergeschaltet.","o":["Ein Wechselventil","Ein Druckschaltventil (Folgeventil)","Ein Schnellentlüftungsventil","Ein Schalldämpfer"],"r":1},{"id":"IM-ph-09","teil":"IMA","g":"imph","th":"Hydraulikpumpe","n":2,"q":"Eine Hydraulikpumpe hat das Verdrängungsvolumen 16 cm³ je Umdrehung und dreht mit 1500 1/min. Wie groß ist der Volumenstrom (ohne Verluste)?","w":"Q = V · n = 16 cm³ · 1500 1/min = 24 000 cm³/min = 24 l/min.","o":["24 l/min","2,4 l/min","240 l/min","94 l/min"],"r":0},{"id":"IM-ph-10","teil":"IMA","g":"imph","th":"Kolbengeschwindigkeit","n":3,"q":"Ein Hydraulikzylinder mit der Kolbenfläche 20 cm² erhält den Volumenstrom 12 l/min. Wie schnell fährt der Kolben aus?","w":"v = Q / A = 12 000 cm³/min / 20 cm² = 600 cm/min = 6 m/min = 0,1 m/s.","o":["0,1 m/s","0,6 m/s","1 m/s","0,01 m/s"],"r":0},{"id":"IM-ph-11","teil":"IMA","g":"imph","th":"Kolbenkraft","n":2,"q":"Auf die Kolbenfläche 50 cm² eines Hydraulikzylinders wirkt der Druck 100 bar. Wie groß ist die Kolbenkraft (ohne Reibung)?","w":"100 bar = 1000 N/cm². F = p · A = 1000 N/cm² · 50 cm² = 50 000 N = 50 kN.","o":["5 kN","50 kN","500 kN","2 kN"],"r":1},{"id":"IM-ph-12","teil":"IMA","g":"imph","th":"Zylinder","n":2,"q":"Ein Differentialzylinder wird beim Aus- und Einfahren mit gleichem Druck und gleichem Volumenstrom versorgt. Was gilt?","w":"Auf der Stangenseite ist die wirksame Fläche um den Stangenquerschnitt kleiner. Kleinere Fläche bedeutet kleinere Kraft, aber höhere Geschwindigkeit.","o":["Er fährt mit kleinerer Kraft aus und mit kleinerer Geschwindigkeit ein","Kraft und Geschwindigkeit sind in beiden Richtungen gleich","Er fährt mit größerer Kraft aus und mit größerer Geschwindigkeit ein","Er fährt schneller aus als ein, die Kraft ist gleich"],"r":2},{"id":"IM-ph-13","teil":"IMA","g":"imph","th":"Sperrventile","n":2,"q":"Ein Hydraulikzylinder soll eine Last auch bei stehender Pumpe sicher in Position halten. Welches Ventil wird dafür eingebaut?","w":"Das entsperrbare Rückschlagventil sperrt leckölfrei und öffnet erst durch einen Steuerdruck. Schieberventile allein haben Lecköl, die Last würde langsam absinken.","o":["Drosselventil","Druckbegrenzungsventil","Wechselventil","Entsperrbares Rückschlagventil"],"r":3},{"id":"IM-ph-14","teil":"IMA","g":"imph","th":"Wegeventile","n":3,"q":"Ein 4/3-Wegeventil hat in der Mittelstellung P mit T verbunden, A und B sind gesperrt (Umlaufstellung). Was bewirkt das?","w":"Der drucklose Umlauf spart Energie und vermeidet Erwärmung des Öls. Bei gesperrter Mittelstellung würde die Pumpe über das Druckbegrenzungsventil fördern.","o":["Die Pumpe fördert nahezu drucklos in den Tank, der Zylinder bleibt eingespannt stehen","Der Zylinder ist frei verschiebbar, die Pumpe arbeitet gegen das Druckbegrenzungsventil","Der Zylinder fährt langsam aus","Die Pumpe wird abgeschaltet"],"r":0},{"id":"IM-ph-15","teil":"IMA","g":"imph","th":"Stromventile","n":3,"q":"Worin unterscheidet sich ein Stromregelventil von einem einfachen Drosselventil?","w":"Bei der Drossel hängt der Durchfluss vom Druckgefälle ab und ändert sich mit der Last. Das Stromregelventil gleicht das mit einer Druckwaage aus.","o":["Es begrenzt den Druck der Anlage","Es hält den Volumenstrom auch bei wechselnder Last nahezu konstant","Es sperrt den Durchfluss in einer Richtung vollständig","Es wirkt nur beim Einfahren des Zylinders"],"r":1},{"id":"IM-ph-16","teil":"IMA","g":"imph","th":"Hydrospeicher","n":2,"q":"Was ist vor Arbeiten an einer Hydraulikanlage mit Hydrospeicher zu beachten?","w":"Der Hydrospeicher hält auch bei abgeschalteter Pumpe Druckenergie bereit. Ohne Entlastung können sich Zylinder bewegen oder Öl unter Druck austreten.","o":["Der Speicher muss vollständig aufgeladen werden","Der Speicher wird mit Druckluft nachgefüllt","Der Speicher muss flüssigkeitsseitig druckentlastet werden","Nichts, bei stehender Pumpe ist die Anlage drucklos"],"r":2},{"id":"IM-ph-17","teil":"IMA","g":"imph","th":"Druckflüssigkeit","n":2,"q":"Wie verhält sich die Viskosität von Hydrauliköl bei steigender Temperatur?","w":"Zu dünnes Öl schmiert schlechter und erhöht die Leckverluste. Deshalb wird die Betriebstemperatur überwacht und das Öl bei Bedarf gekühlt.","o":["Sie nimmt zu, das Öl wird zähflüssiger","Sie bleibt immer gleich","Sie steigt zuerst und fällt dann auf null","Sie nimmt ab, das Öl wird dünnflüssiger"],"r":3},{"id":"IM-ph-18","teil":"IMA","g":"imph","th":"Vergleich","n":1,"q":"Warum eignet sich die Pneumatik weniger gut für gleichmäßige, langsame Bewegungen unter wechselnder Last als die Hydraulik?","w":"Hydrauliköl ist nahezu inkompressibel und überträgt Bewegungen gleichmäßig bei hohen Kräften. Pneumatik ist schnell, sauber und einfach, aber weich.","o":["Luft ist kompressibel, der Kolben federt und ruckt","Luft ist zu schwer","Druckluft ist nicht speicherbar","Pneumatikzylinder haben keine Dichtungen"],"r":0},{"id":"IM-ph-19","teil":"IMA","g":"imph","th":"Druckluftaufbereitung","n":2,"q":"Warum fällt in Druckluftanlagen Kondensat an?","w":"Die angesaugte Luft enthält Wasserdampf. Nach Verdichten und Abkühlen fällt Wasser aus. Trockner, Kondensatabscheider und Leitungen mit Gefälle halten es von der Anlage fern.","o":["Der Verdichter wird mit Wasser geschmiert","Die verdichtete Luft kühlt ab und kann dann weniger Wasserdampf halten","Die Leitungen sind undicht und saugen Regenwasser an","Das Kondensat entsteht aus dem Öl der Wartungseinheit"],"r":1},{"id":"IM-ph-20","teil":"IMA","g":"imph","th":"Störungen","n":3,"q":"Eine Hydraulikpumpe arbeitet plötzlich sehr laut und prasselnd. Welche Ursache ist wahrscheinlich?","w":"Bei zu großem Unterdruck in der Saugleitung bilden sich Dampfblasen, die schlagartig zusammenfallen. Das zerstört die Pumpe. Auch angesaugte Luft macht ähnliche Geräusche.","o":["Zu niedrig eingestellter Druck am Druckbegrenzungsventil","Ein zu großer Tank","Ein zu dünnes Manometerrohr","Kavitation, zum Beispiel durch einen verstopften Saugfilter oder zu niedrigen Ölstand"],"r":3},{"id":"IM-ph-N01","teil":"IMA","g":"imph","th":"Kolbenkraft","n":2,"q":"Ein Hydraulikzylinder mit 63 mm Kolbendurchmesser wird mit 80 bar beaufschlagt. Berechnen Sie die Kolbenkraft beim Ausfahren in kN (ohne Reibung).","w":"A = π · (6,3 cm)² / 4 = 31,17 cm². F = 800 N/cm² · 31,17 cm² ≈ 24 940 N = 24,94 kN.","ans":24.94,"u":"kN","tol":0.02},{"id":"IM-ph-N02","teil":"IMA","g":"imph","th":"Volumenstrom","n":3,"q":"Ein Hydraulikzylinder mit der Kolbenfläche 10 cm² soll mit 0,05 m/s ausfahren. Berechnen Sie den nötigen Volumenstrom in l/min.","w":"Q = A · v = 10 cm² · 5 cm/s = 50 cm³/s = 3000 cm³/min = 3 l/min.","ans":3,"u":"l/min","tol":0.02},{"id":"IM-sp-01","teil":"IMA","g":"imsp","th":"Magnetventile","n":2,"q":"Wie verhält sich ein federrückgestelltes 5/2-Magnetventil bei Spannungsausfall?","w":"Monostabile Ventile haben eine definierte Ruhestellung. Impulsventile mit zwei Spulen behalten bei Spannungsausfall ihre Stellung.","o":["Es bleibt in der zuletzt geschalteten Stellung","Es schaltet in eine gesperrte Mittelstellung","Es schaltet ständig hin und her","Es schaltet durch die Feder in die Ruhestellung zurück"],"r":3},{"id":"IM-sp-02","teil":"IMA","g":"imsp","th":"Relaisschaltungen","n":2,"q":"Wie entsteht in einer Relaissteuerung eine Selbsthaltung?","w":"Nach dem Loslassen des Tasters fließt der Spulenstrom über den eigenen Schließer weiter. Ein Aus-Taster als Öffner in Reihe unterbricht die Selbsthaltung.","o":["Ein Schließer des Relais liegt parallel zum Ein-Taster","Ein Öffner des Relais liegt parallel zum Ein-Taster","Ein Schließer des Relais liegt in Reihe zum Ein-Taster","Der Ein-Taster wird mechanisch verklemmt"],"r":0},{"id":"IM-sp-03","teil":"IMA","g":"imsp","th":"Kontakte","n":1,"q":"Welche Funktionsziffern kennzeichnen an einem Relais oder Taster einen Schließer?","w":"Schließer tragen die Funktionsziffern 3-4, Öffner 1-2. Die Ziffer davor zählt die Kontakte durch. A1 und A2 sind die Spulenanschlüsse.","o":["1 und 2 (zum Beispiel 11-12)","3 und 4 (zum Beispiel 13-14)","5 und 6","A1 und A2"],"r":1},{"id":"IM-sp-04","teil":"IMA","g":"imsp","th":"Sensoren","n":2,"q":"Mit welchem Sensor wird die Kolbenstellung eines Pneumatikzylinders mit Magnetring am Kolben von außen erfasst?","w":"Der Magnetring im Kolben betätigt den Sensor durch das nicht magnetische Zylinderrohr hindurch.","o":["Kapazitiver Näherungsschalter an der Kolbenstange","Einweg-Lichtschranke durch das Zylinderrohr","Magnetischer Näherungsschalter (zum Beispiel Reedschalter) am Zylinderrohr","Druckschalter in der Zuleitung"],"r":2},{"id":"IM-sp-05","teil":"IMA","g":"imsp","th":"Sensoren","n":1,"q":"Welche Gegenstände erkennt ein induktiver Näherungsschalter?","w":"Der induktive Sensor erzeugt ein hochfrequentes Magnetfeld, das von Metallen bedämpft wird. Kapazitive Sensoren erkennen auch Nichtmetalle.","o":["Alle Stoffe, auch Glas und Flüssigkeiten","Nur magnetisierte Teile","Nur durchsichtige Kunststoffe","Metallische Gegenstände"],"r":3},{"id":"IM-sp-06","teil":"IMA","g":"imsp","th":"Sensoren","n":2,"q":"Was kennzeichnet eine Reflexionslichtschranke?","w":"Getrennte Gehäuse hat die Einweglichtschranke. Wird das Licht vom Objekt zurückgeworfen, spricht man vom Reflexionslichttaster.","o":["Sender und Empfänger sitzen in einem Gehäuse, gegenüber ist ein Reflektor angebracht","Sender und Empfänger sitzen in getrennten Gehäusen gegenüber","Sie braucht keinen Reflektor, das Objekt selbst wirft das Licht zurück","Sie arbeitet mit Ultraschall statt mit Licht"],"r":0},{"id":"IM-sp-07","teil":"IMA","g":"imsp","th":"SPS","n":2,"q":"Wie arbeitet eine SPS ihr Programm ab?","w":"Zu Beginn jedes Zyklus wird das Prozessabbild der Eingänge gelesen, am Ende das Prozessabbild der Ausgänge ausgegeben. Die Zykluszeit liegt meist im Millisekundenbereich.","o":["Einmalig nach dem Einschalten, danach bleiben die Ausgänge fest","Zyklisch: Eingänge einlesen, Programm abarbeiten, Ausgänge ausgeben","Nur, wenn ein Eingang seinen Zustand wechselt, sonst ruht sie","Alle Anweisungen gleichzeitig ohne Reihenfolge"],"r":1},{"id":"IM-sp-08","teil":"IMA","g":"imsp","th":"SPS","n":1,"q":"Welchen Vorteil hat eine SPS gegenüber einer verbindungsprogrammierten Relaissteuerung?","w":"Die Logik steckt bei der SPS im Programm. Bei der Relaissteuerung ist sie durch die Verdrahtung festgelegt.","o":["Sie braucht keine Sensoren und Aktoren","Sie kommt ohne Stromversorgung aus","Der Ablauf lässt sich durch Ändern des Programms anpassen, ohne die Verdrahtung umzubauen","Sie macht Not-Halt-Einrichtungen überflüssig"],"r":2},{"id":"IM-sp-09","teil":"IMA","g":"imsp","th":"Logik","n":1,"q":"An einer UND-Verknüpfung mit zwei Eingängen liegt E1 = 1 und E2 = 0. Welchen Zustand hat der Ausgang?","w":"Die UND-Verknüpfung liefert nur 1, wenn alle Eingänge 1 sind. Eine ODER-Verknüpfung würde hier 1 liefern.","o":["1","Er wechselt ständig zwischen 0 und 1","Er behält den letzten Zustand","0"],"r":3},{"id":"IM-sp-10","teil":"IMA","g":"imsp","th":"Drahtbruchsicherheit","n":2,"q":"Warum werden Stopp- und Not-Halt-Taster als Öffner ausgeführt?","w":"Bei einem Schließer bliebe ein Drahtbruch unbemerkt, die Anlage ließe sich nicht mehr anhalten. Dieses Prinzip heißt Drahtbruchsicherheit.","o":["Öffner sind billiger als Schließer","Öffner schalten schneller als Schließer","Die SPS kann Schließer nicht auswerten","Ein Drahtbruch wirkt dann wie ein Stopp-Befehl, die Anlage geht in den sicheren Zustand"],"r":3},{"id":"IM-sp-11","teil":"IMA","g":"imsp","th":"Zeitfunktionen","n":2,"q":"Wie verhält sich eine Einschaltverzögerung (TON) mit 5 s?","w":"Das sofortige Einschalten mit verzögertem Abfallen ist die Ausschaltverzögerung (TOF).","o":["Der Ausgang wird sofort 1 und fällt 5 s nach dem Eingang ab","Der Ausgang gibt nach dem Start einen Impuls von genau 5 s ab, unabhängig vom Eingang","Der Ausgang wird 1, wenn der Eingang 5 s lang ununterbrochen 1 war, und fällt mit dem Eingang sofort ab","Der Ausgang blinkt im Takt von 5 s"],"r":2},{"id":"IM-sp-12","teil":"IMA","g":"imsp","th":"Sensoren","n":2,"q":"Welche Aderfarben hat ein dreiadriger Näherungsschalter für 24 V Gleichspannung üblicherweise?","w":"Die Aderfarben sind genormt. Grün-Gelb ist ausschließlich dem Schutzleiter vorbehalten.","o":["Blau: +24 V, Braun: 0 V, Schwarz: Schaltausgang","Braun: +24 V, Blau: 0 V, Schwarz: Schaltausgang","Schwarz: +24 V, Blau: Schaltausgang, Braun: 0 V","Grün-Gelb: +24 V, Blau: 0 V, Braun: Schaltausgang"],"r":1},{"id":"IM-sp-13","teil":"IMA","g":"imsp","th":"Schaltpläne","n":1,"q":"In welchem Zustand werden Kontakte und Geräte im Stromlaufplan dargestellt?","w":"Schließer sind offen, Öffner geschlossen gezeichnet. Abweichungen müssen besonders gekennzeichnet sein.","o":["Spannungslos und unbetätigt","Unter Spannung und betätigt","Im Zustand der letzten Störung","Im Zustand während des Automatikbetriebs"],"r":0},{"id":"IM-sp-14","teil":"IMA","g":"imsp","th":"Signalarten","n":1,"q":"Welches Signal ist ein analoges Signal?","w":"Ein analoges Signal kann innerhalb seines Bereichs jeden Zwischenwert annehmen. Binäre Signale kennen nur zwei Zustände.","o":["Das Signal eines Endschalters","Das Signal eines Tasters","Das Signal eines Reedkontakts","Der Strom 4 mA bis 20 mA eines Drucksensors"],"r":3},{"id":"IM-sp-15","teil":"IMA","g":"imsp","th":"Elektrische Sicherheit","n":1,"q":"Welche der fünf Sicherheitsregeln steht an erster Stelle?","w":"Reihenfolge: Freischalten, gegen Wiedereinschalten sichern, Spannungsfreiheit feststellen, Erden und Kurzschließen, benachbarte unter Spannung stehende Teile abdecken oder abschranken.","o":["Erden und kurzschließen","Spannungsfreiheit feststellen","Freischalten","Benachbarte, unter Spannung stehende Teile abdecken"],"r":2},{"id":"IM-sp-16","teil":"IMA","g":"imsp","th":"Elektropneumatik","n":2,"q":"Welche Aufgabe hat ein Relais in einer elektropneumatischen Steuerung?","w":"Mit seinen Schließern und Öffnern bildet das Relais Verknüpfungen, Selbsthaltungen und Verriegelungen. Die Spule ist vom Lastkreis galvanisch getrennt.","o":["Es wandelt Druckluft in elektrischen Strom um","Es verknüpft und vervielfacht Signale und schaltet mit kleinem Steuerstrom größere Lasten","Es misst den Druck im Zylinder","Es drosselt die Abluft des Zylinders"],"r":1},{"id":"IM-ap-01","teil":"IMF","g":"imap","th":"Arbeitsplan","n":1,"q":"Was legt ein Arbeitsplan für ein Einzelteil fest?","w":"Der Arbeitsplan beschreibt, wie und womit gefertigt wird. Maße und Toleranzen stehen in der Zeichnung.","o":["Die Preise und Lieferzeiten der Zulieferer","Reihenfolge der Arbeitsschritte mit Maschinen, Werkzeugen, Spannmitteln, Schnittdaten und Prüfmitteln","Die Urlaubsplanung der Abteilung","Nur die Maße und Toleranzen des Teils"],"r":1},{"id":"IM-ap-02","teil":"IMF","g":"imap","th":"Arbeitsfolge","n":2,"q":"Eine Grundplatte wird aus einem gesägten Rohteil gefräst und gebohrt. Welche Reihenfolge ist sinnvoll?","w":"Zuerst entstehen die Bezugsflächen, von denen aus alle weiteren Maße gefertigt und geprüft werden. Bohrungen kommen nach den Außenflächen, weil ihre Lage von diesen abhängt.","o":["Bohren und senken, Außenmaße fräsen, Rohteil prüfen, Bezugsflächen fräsen","Entgraten, prüfen, Bezugsflächen fräsen, bohren","Rohteil prüfen, Bezugsflächen fräsen, Außenmaße fräsen, bohren und senken, entgraten, prüfen","Außenmaße fräsen, prüfen, Rohteil prüfen, bohren, Bezugsflächen fräsen"],"r":2},{"id":"IM-ap-03","teil":"IMF","g":"imap","th":"Auftragszeit","n":2,"q":"Für einen Auftrag über 25 Teile gelten die Rüstzeit 30 min und die Zeit je Einheit 4 min. Wie groß ist die Auftragszeit?","w":"T = tr + m · te = 30 min + 25 · 4 min = 130 min.","o":["34 min","850 min","100 min","130 min"],"r":3},{"id":"IM-ap-04","teil":"IMF","g":"imap","th":"Kosten","n":1,"q":"Eine Fräsmaschine hat einen Maschinenstundensatz von 60 Euro je Stunde. Was kostet eine Bearbeitung von 45 Minuten?","w":"45 min = 0,75 h. 0,75 h · 60 Euro/h = 45 Euro.","o":["45 Euro","27 Euro","80 Euro","2700 Euro"],"r":0},{"id":"IM-ap-05","teil":"IMF","g":"imap","th":"Rohteil","n":2,"q":"Ein Drehteil hat den größten Durchmesser 47 mm und die Fertiglänge 118 mm. Je Stirnseite sind 2 mm Planzugabe vorgesehen. Im Lager liegt Rundstahl mit Ø45, Ø50 und Ø60. Welches Rohteil wird abgesägt?","w":"Der nächstgrößere Durchmesser über 47 mm ist Ø50. Länge: 118 mm + 2 · 2 mm = 122 mm.","o":["Ø45 mm, 118 mm lang","Ø50 mm, 122 mm lang","Ø50 mm, 118 mm lang","Ø60 mm, 120 mm lang"],"r":1},{"id":"IM-ap-06","teil":"IMF","g":"imap","th":"Aufspannung","n":2,"q":"Warum werden an einem Drehteil möglichst viele Flächen in einer Aufspannung bearbeitet?","w":"Jedes Umspannen bringt Spannfehler mit. Flächen aus einer Aufspannung haben dieselbe Drehachse.","o":["Das Werkzeug verschleißt dann nicht","Die Schnittgeschwindigkeit darf dann höher sein","Die Flächen laufen dann genau zueinander (Rundlauf, Koaxialität)","Die Oberflächen werden dann automatisch gehärtet"],"r":2},{"id":"IM-ap-07","teil":"IMF","g":"imap","th":"Unterlagen","n":1,"q":"Welche Unterlage nennt für eine Baugruppe alle Einzelteile und Normteile mit Menge und Benennung?","w":"Die Stückliste gehört zur Gesamtzeichnung. Über die Positionsnummern sind Zeichnung und Stückliste verknüpft.","o":["Der Arbeitsplan","Das Prüfprotokoll","Der Wartungsplan","Die Stückliste"],"r":3},{"id":"IM-ap-08","teil":"IMF","g":"imap","th":"Standzeit","n":2,"q":"Wie wirkt sich eine höhere Schnittgeschwindigkeit auf die Standzeit der Werkzeugschneide aus?","w":"Mit der Schnittgeschwindigkeit steigt die Temperatur an der Schneide, der Verschleiß nimmt stark zu. Die Standzeit ist die Eingriffszeit bis zum Nachschleifen oder Wechseln.","o":["Die Standzeit wird kürzer","Die Standzeit wird länger","Die Standzeit bleibt gleich","Die Standzeit hängt nur vom Werkstück ab, nicht von der Schnittgeschwindigkeit"],"r":0},{"id":"IM-ap-09","teil":"IMF","g":"imap","th":"Zeitspanvolumen","n":3,"q":"Beim Längsdrehen betragen die Schnitttiefe 3 mm, der Vorschub 0,25 mm und die Schnittgeschwindigkeit 160 m/min. Wie groß ist das Zeitspanvolumen Q = ap · f · vc?","w":"Q = 3 mm · 0,25 mm · 160 m/min = 0,75 mm² · 160 m/min = 120 cm³/min (1 mm² · 1 m = 1 cm³).","o":["12 cm³/min","120 cm³/min","1200 cm³/min","480 cm³/min"],"r":1},{"id":"IM-ap-10","teil":"IMF","g":"imap","th":"Rüstzeit","n":2,"q":"Wie verändert sich der Rüstzeitanteil je Werkstück, wenn die Losgröße steigt?","w":"Die Rüstzeit fällt je Auftrag einmal an. Bei kleinen Losen bestimmt sie die Kosten stark.","o":["Er steigt, weil öfter gerüstet werden muss","Er sinkt, weil sich die einmalige Rüstzeit auf mehr Teile verteilt","Er bleibt gleich","Er entfällt bei jeder Losgröße über 10 Stück"],"r":1},{"id":"IM-ap-11","teil":"IMF","g":"imap","th":"Terminplanung","n":1,"q":"Was zeigt ein Balkendiagramm (Gantt-Diagramm) in der Arbeitsplanung?","w":"Jeder Arbeitsgang ist ein Balken über der Zeitachse. So sind Überschneidungen, Reihenfolge und Endtermin erkennbar.","o":["Dauer und zeitliche Lage der Arbeitsgänge","Die Maßabweichungen der gefertigten Teile","Den Schaltzustand der Ventile","Die Häufigkeit von Fehlerursachen"],"r":0},{"id":"IM-ap-N01","teil":"IMF","g":"imap","th":"Auftragszeit","n":2,"q":"Für einen Auftrag über 40 Teile gelten die Rüstzeit 20 min und die Zeit je Einheit 2,5 min. Berechnen Sie die Auftragszeit in min.","w":"T = tr + m · te = 20 min + 40 · 2,5 min = 120 min.","ans":120,"u":"min","tol":0.02},{"id":"IM-cn-01","teil":"IMF","g":"imcn","th":"Koordinatenachsen","n":1,"q":"Wie liegt die Z-Achse an einer CNC-Drehmaschine?","w":"Die Z-Achse liegt bei Werkzeugmaschinen in Richtung der Arbeitsspindel. Bei der Drehmaschine ist X die Planrichtung.","o":["Quer zur Drehachse in Richtung des Durchmessers","In Richtung der Hauptspindelachse","Senkrecht nach oben","Parallel zur Reitstockpinole, aber quer zur Spindel"],"r":1},{"id":"IM-cn-02","teil":"IMF","g":"imcn","th":"Koordinatenachsen","n":2,"q":"Wie sind die Achsen X, Y und Z bei der Rechte-Hand-Regel zugeordnet?","w":"Die Finger der rechten Hand zeigen in die positiven Achsrichtungen des rechtwinkligen Koordinatensystems.","o":["Daumen Z, Zeigefinger X, Mittelfinger Y","Daumen Y, Zeigefinger Z, Mittelfinger X","Daumen X, Zeigefinger Y, Mittelfinger Z","Daumen X, Zeigefinger Z, Mittelfinger Y"],"r":2},{"id":"IM-cn-03","teil":"IMF","g":"imcn","th":"Wegbedingungen","n":1,"q":"Was bewirkt G00?","w":"Mit G00 wird ohne Werkzeugeingriff schnell positioniert. G01 fährt eine Gerade im programmierten Vorschub.","o":["Geradeninterpolation im Arbeitsvorschub","Kreisinterpolation im Uhrzeigersinn","Programmhalt","Positionieren im Eilgang"],"r":3},{"id":"IM-cn-04","teil":"IMF","g":"imcn","th":"Wegbedingungen","n":1,"q":"Mit welcher Wegbedingung wird ein Kreisbogen im Uhrzeigersinn gefahren?","w":"G02: Kreisinterpolation im Uhrzeigersinn, G03: gegen den Uhrzeigersinn.","o":["G02","G03","G01","G00"],"r":0},{"id":"IM-cn-05","teil":"IMF","g":"imcn","th":"Maßangaben","n":2,"q":"Das Werkzeug steht auf X20 Y10. Es folgt der Satz G91 G01 X15 Y-5. Auf welcher Position steht das Werkzeug danach?","w":"G91 bedeutet Kettenmaß (inkremental): Die Werte werden zur aktuellen Position addiert. X = 20 + 15 = 35, Y = 10 - 5 = 5.","o":["X15 Y-5","X35 Y5","X5 Y15","X35 Y15"],"r":1},{"id":"IM-cn-06","teil":"IMF","g":"imcn","th":"Zusatzfunktionen","n":1,"q":"Was bewirkt M30?","w":"M30 beendet das Programm und setzt es an den Anfang zurück. M03 schaltet die Spindel im Uhrzeigersinn ein, M08 das Kühlschmiermittel.","o":["Spindel ein im Uhrzeigersinn","Kühlschmiermittel ein","Programmende mit Rücksprung zum Programmanfang","Werkzeugwechsel"],"r":2},{"id":"IM-cn-07","teil":"IMF","g":"imcn","th":"Zusatzfunktionen","n":1,"q":"Mit welchem Befehl wird die Spindel im Uhrzeigersinn (Rechtslauf) eingeschaltet?","w":"M03: Rechtslauf, M04: Linkslauf, M05: Spindel halt, M08: Kühlschmiermittel ein.","o":["M04","M05","M08","M03"],"r":3},{"id":"IM-cn-08","teil":"IMF","g":"imcn","th":"Adressbuchstaben","n":1,"q":"Was wird mit den Adressen F, S und T programmiert?","w":"F kommt von feed, S von speed, T von tool.","o":["F Vorschub, S Drehzahl oder Schnittgeschwindigkeit, T Werkzeug","F Werkzeug, S Vorschub, T Drehzahl","F Drehzahl, S Werkzeug, T Vorschub","F Satznummer, S Unterprogramm, T Verweilzeit"],"r":0},{"id":"IM-cn-09","teil":"IMF","g":"imcn","th":"Bezugspunkte","n":2,"q":"Welche Aussage zum Werkstücknullpunkt ist richtig?","w":"Unveränderlich ist der Maschinennullpunkt. Der Werkstücknullpunkt wird so gelegt, dass die Zeichnungsmaße direkt übernommen werden können.","o":["Er wird vom Maschinenhersteller festgelegt und ist nicht veränderbar","Er wird vom Programmierer festgelegt und ist der Ursprung der programmierten Koordinaten","Er liegt immer in der Werkzeugspitze","Er ist nur bei Handbetrieb von Bedeutung"],"r":1},{"id":"IM-cn-10","teil":"IMF","g":"imcn","th":"Werkzeugkorrektur","n":2,"q":"Was bewirkt G41 beim Fräsen einer Kontur?","w":"G41: links der Kontur, G42: rechts der Kontur, G40: Korrektur aus. Programmiert wird die Werkstückkontur, die Steuerung berechnet die Fräsermittelpunktsbahn.","o":["Fräserradiuskorrektur, das Werkzeug fährt rechts der Kontur","Fräserradiuskorrektur, das Werkzeug fährt in Vorschubrichtung gesehen links der Kontur","Die Radiuskorrektur wird ausgeschaltet","Die Werkzeuglängenkorrektur wird gelöscht"],"r":1},{"id":"IM-cn-11","teil":"IMF","g":"imcn","th":"Schnittgeschwindigkeit","n":2,"q":"Beim Plandrehen von außen zur Mitte ist G96 (konstante Schnittgeschwindigkeit) aktiv. Was geschieht mit der Drehzahl?","w":"n = vc · 1000 / (π · d): Bei konstantem vc steigt n mit sinkendem d. Deshalb wird zusätzlich eine Drehzahlbegrenzung programmiert.","o":["Sie steigt, je kleiner der Durchmesser wird","Sie sinkt, je kleiner der Durchmesser wird","Sie bleibt konstant","Sie wird auf null gesetzt"],"r":0},{"id":"IM-cn-12","teil":"IMF","g":"imcn","th":"Satzaufbau","n":1,"q":"Wofür steht das N am Anfang eines CNC-Satzes, zum Beispiel N40 G01 X50 F0.2?","w":"Die Satznummer dient der Übersicht und als Sprungziel. Die Reihenfolge der Abarbeitung richtet sich nach der Reihenfolge im Programm.","o":["Für die Drehzahl","Für die Anzahl der Wiederholungen","Für den Werkzeugradius","Für die Satznummer"],"r":3},{"id":"IM-cn-13","teil":"IMF","g":"imcn","th":"Einfahren","n":2,"q":"Wie wird ein neues CNC-Programm sicher eingefahren?","w":"Simulation und Einzelsatzbetrieb decken Programmier- und Einrichtfehler auf, bevor es zur Kollision kommt. Schutzeinrichtungen werden nie überbrückt.","o":["Sofort im Automatikbetrieb mit vollem Eilgang starten","Mit geöffneter Schutztür und überbrücktem Türschalter beobachten","Erst simulieren, dann im Einzelsatz mit reduziertem Eilgang und Vorschub abfahren","Ohne Werkzeugkorrekturwerte starten und diese später nachtragen"],"r":2},{"id":"IM-cn-14","teil":"IMF","g":"imcn","th":"Drehen","n":2,"q":"An einer CNC-Drehmaschine mit Durchmesserprogrammierung steht im Satz X40. Wo steht die Werkzeugschneide?","w":"Bei der Durchmesserprogrammierung wird der X-Wert als Durchmesser angegeben. So können die Zeichnungsmaße direkt übernommen werden.","o":["40 mm von der Drehachse entfernt, also auf Durchmesser 80 mm","Auf dem Durchmesser 40 mm, also 20 mm von der Drehachse entfernt","40 mm vor der Planfläche","Auf dem Radius 40 mm"],"r":1},{"id":"IM-cn-15","teil":"IMF","g":"imcn","th":"Kreisinterpolation","n":3,"q":"Ein Kreisbogen beginnt bei X20 Y30. Im Satz stehen die inkrementalen Mittelpunktkoordinaten I10 J0 (bezogen auf den Startpunkt). Wo liegt der Kreismittelpunkt?","w":"I gilt für die X-Richtung, J für die Y-Richtung. Mittelpunkt: X = 20 + 10 = 30, Y = 30 + 0 = 30.","o":["X30 Y30","X10 Y0","X20 Y40","X10 Y30"],"r":0},{"id":"IM-cn-N01","teil":"IMF","g":"imcn","th":"Maßangaben","n":2,"q":"Das Werkzeug steht auf X12. Nacheinander folgen im Kettenmaß (G91) die Wege X+25, X-8 und X+16. Auf welcher X-Position steht das Werkzeug danach?","w":"Kettenmaße werden addiert: 12 + 25 - 8 + 16 = 45.","ans":45,"u":"mm","tol":0},{"id":"IM-mo-01","teil":"IMF","g":"immo","th":"Vorbereitung","n":1,"q":"Was ist vor der Demontage einer Baugruppe sinnvoll, deren Teile in einer bestimmten Lage zueinander stehen müssen?","w":"Markierungen und eine geordnete Ablage erleichtern die spätere Montage und verhindern Verwechslungen.","o":["Alle Teile in eine gemeinsame Kiste legen","Die Passstifte ausbohren","Die Lage der Teile zueinander kennzeichnen und die Reihenfolge festhalten","Alle Schrauben nach Größe sortiert entsorgen"],"r":2},{"id":"IM-mo-02","teil":"IMF","g":"immo","th":"Schrauben anziehen","n":1,"q":"In welcher Reihenfolge werden die Schrauben eines Flanschdeckels angezogen?","w":"So legt sich der Deckel gleichmäßig an, die Dichtung wird gleichmäßig gepresst und das Bauteil verzieht sich nicht.","o":["Im Kreis herum, jede Schraube sofort mit vollem Drehmoment","Über Kreuz und in mehreren Stufen bis zum vorgeschriebenen Drehmoment","Zuerst eine Seite vollständig, dann die andere","Die Reihenfolge ist ohne Bedeutung"],"r":1},{"id":"IM-mo-03","teil":"IMF","g":"immo","th":"Schrauben anziehen","n":1,"q":"Wozu wird ein Drehmomentschlüssel verwendet?","w":"Zu geringe Vorspannung führt zum Lockern, zu hohe überdehnt die Schraube.","o":["Um die Schraube mit einem festgelegten Drehmoment anzuziehen und so die Vorspannkraft zu erreichen","Um festsitzende Schrauben mit einem Schlag zu lösen","Um die Gewindesteigung zu messen","Um Schrauben schneller eindrehen zu können"],"r":0},{"id":"IM-mo-04","teil":"IMF","g":"immo","th":"Lagerdemontage","n":2,"q":"Ein Rillenkugellager sitzt mit festem Sitz auf einer Welle und soll wiederverwendet werden. Wo setzt der Abzieher an?","w":"Die Abziehkraft muss am fest sitzenden Ring angreifen. Über den Außenring würde sie durch die Wälzkörper laufen und die Laufbahnen eindrücken.","o":["Am Außenring","Am Käfig","An der Dichtscheibe","Am Innenring"],"r":3},{"id":"IM-mo-05","teil":"IMF","g":"immo","th":"Wärmedehnung","n":3,"q":"Eine Stahlnabe mit 100 mm Bohrungsdurchmesser wird um 150 K erwärmt (Längenausdehnungskoeffizient 0,000012 1/K). Um wie viel wächst der Bohrungsdurchmesser?","w":"Δd = α · d · ΔT = 0,000012 1/K · 100 mm · 150 K = 0,18 mm.","o":["0,018 mm","1,8 mm","0,18 mm","0,012 mm"],"r":2},{"id":"IM-mo-06","teil":"IMF","g":"immo","th":"Ausrichten","n":2,"q":"Welche Fehler werden beim Ausrichten zweier Wellen an einer Kupplung beseitigt?","w":"Geprüft wird mit Haarlineal und Fühlerlehre, mit Messuhren oder mit einem Laserausrichtgerät. Fluchtungsfehler belasten Lager, Dichtungen und Kupplung.","o":["Unwucht und Lagerspiel","Radialversatz (Parallelversatz) und Winkelversatz","Rauheit und Härte der Wellenenden","Übersetzung und Drehrichtung"],"r":1},{"id":"IM-mo-07","teil":"IMF","g":"immo","th":"Dichtungen","n":2,"q":"Wie wird ein Radialwellendichtring über ein Wellenende mit Passfedernut montiert?","w":"Scharfe Kanten zerschneiden die Dichtlippe. Die Hülse deckt Nut und Kanten ab. Ausgebaute Dichtringe werden nicht wiederverwendet.","o":["Mit einer Montagehülse, Dichtlippe leicht geölt","Trocken und mit einem Schraubendreher über die Kante gehebelt","Mit dem Hammer direkt auf die Dichtlippe geschlagen","Nach dem Erwärmen auf 200 °C"],"r":0},{"id":"IM-mo-08","teil":"IMF","g":"immo","th":"Sauberkeit","n":1,"q":"Wann wird ein neues Wälzlager aus der Verpackung genommen?","w":"Schmutz ist die häufigste Ursache früher Lagerschäden. Das Konservierungsmittel verträgt sich in der Regel mit dem Schmierstoff und wird nicht ausgewaschen.","o":["Am Vortag, damit es die Raumtemperatur annimmt und entfettet werden kann","Sobald es geliefert wird, zur Lagerung im offenen Regal","Eine Woche vorher, damit das Konservierungsmittel verdunstet","Erst unmittelbar vor dem Einbau"],"r":3},{"id":"IM-mo-09","teil":"IMF","g":"immo","th":"Inbetriebnahme","n":2,"q":"Was gehört zur Inbetriebnahme nach einer Montage?","w":"Erst prüfen, dann schrittweise belasten. Das Protokoll belegt den Zustand bei der Übergabe.","o":["Sofortiger Dauerbetrieb unter Volllast ohne Prüfung","Entfernen der Schutzeinrichtungen zur besseren Beobachtung","Sicht- und Funktionsprüfung, Probelauf, Prüfung der Schutzeinrichtungen und ein Protokoll","Übergabe ohne Dokumentation"],"r":2},{"id":"IM-mo-10","teil":"IMF","g":"immo","th":"Schrauben lösen","n":2,"q":"Eine Schraube ist bündig im Gewindeloch abgerissen. Wie wird der Rest üblicherweise entfernt?","w":"Der Linksausdreher verkeilt sich beim Linksdrehen in der Bohrung und dreht den Rest heraus. Vorher helfen Kriechöl und bei Bedarf Wärme.","o":["Mit einem größeren Hammer tiefer einschlagen","Mit einem Rechtsgewindebohrer gleicher Größe nachschneiden","Mittig anbohren und mit einem Linksausdreher (Schraubenausdreher) herausdrehen","Mit Klebstoff eine neue Schraube aufsetzen"],"r":2},{"id":"IM-mo-11","teil":"IMF","g":"immo","th":"Sicherheit","n":1,"q":"Was ist vor Montagearbeiten an einer Maschine zuerst zu tun?","w":"Der Hauptschalter wird mit einem persönlichen Schloss gesichert. Druckluft, Hydraulikdruck, Federn und angehobene Lasten sind ebenfalls Energiequellen.","o":["Nur den Not-Halt drücken und sofort beginnen","Die Maschine im Tippbetrieb weiterlaufen lassen","Ein Schild an die Schutztür hängen, das genügt","Hauptschalter ausschalten und gegen Wiedereinschalten sichern, gespeicherte Energien abbauen"],"r":3},{"id":"IM-mo-12","teil":"IMF","g":"immo","th":"Anschlagen von Lasten","n":2,"q":"Welcher Neigungswinkel darf beim Anschlagen einer Last mit einem mehrsträngigen Gehänge nicht überschritten werden?","w":"Je größer der Neigungswinkel, desto größer ist die Kraft in den Strängen. Über 60° ist das Anschlagen nicht zulässig.","o":["60° (gemessen zur Senkrechten)","15°","30°","90°"],"r":0},{"id":"IM-mo-N01","teil":"IMF","g":"immo","th":"Wärmedehnung","n":3,"q":"Ein Lagerinnenring aus Stahl mit 80 mm Bohrung wird um 100 K erwärmt (Längenausdehnungskoeffizient 0,000012 1/K). Berechnen Sie die Aufweitung der Bohrung in mm.","w":"Δd = α · d · ΔT = 0,000012 1/K · 80 mm · 100 K = 0,096 mm.","ans":0.096,"u":"mm","tol":0.02},{"id":"IM-ih-01","teil":"IMF","g":"imih","th":"Grundmaßnahmen","n":1,"q":"Welche Tätigkeit ist eine Wartung im Sinne der Instandhaltung?","w":"Wartung verzögert den Abbau des Abnutzungsvorrats: Reinigen, Schmieren, Nachstellen, Ergänzen. Messen ist Inspektion, Austauschen ist Instandsetzung.","o":["Ein gebrochenes Zahnrad austauschen","Führungsbahnen reinigen und nach Schmierplan abschmieren","Das Lagerspiel messen und beurteilen","Eine Schwachstelle durch eine bessere Konstruktion beseitigen"],"r":1},{"id":"IM-ih-02","teil":"IMF","g":"imih","th":"Grundmaßnahmen","n":1,"q":"Welche Tätigkeit ist eine Instandsetzung?","w":"Instandsetzung führt eine Einheit in den funktionsfähigen Zustand zurück, durch Ausbessern oder Austauschen.","o":["Die Riemenspannung prüfen","Den Ölstand ablesen","Einen verschlissenen Keilriemen ersetzen","Die Maschine reinigen"],"r":2},{"id":"IM-ih-03","teil":"IMF","g":"imih","th":"Grundmaßnahmen","n":2,"q":"Ein offenes Lager fällt wiederholt durch eindringenden Staub aus und wird durch ein abgedichtetes Lager ersetzt. Zu welcher Grundmaßnahme gehört das?","w":"Die Verbesserung erhöht die Zuverlässigkeit oder Instandhaltbarkeit, ohne die Funktion der Maschine zu ändern. Hier wird eine Schwachstelle beseitigt.","o":["Wartung","Inspektion","Stilllegung","Verbesserung"],"r":3},{"id":"IM-ih-04","teil":"IMF","g":"imih","th":"Abnutzungsvorrat","n":2,"q":"Was versteht man unter dem Abnutzungsvorrat eines Bauteils?","w":"Im Betrieb wird der Abnutzungsvorrat abgebaut. Wartung verzögert den Abbau, Instandsetzung füllt den Vorrat wieder auf.","o":["Den Vorrat an möglicher Funktionserfüllung bis zur Abnutzungsgrenze","Den Bestand an Ersatzteilen im Lager","Die Menge des Schmierstoffs im Vorratsbehälter","Die Zahl der bereits ausgeführten Reparaturen"],"r":0},{"id":"IM-ih-05","teil":"IMF","g":"imih","th":"Strategien","n":2,"q":"Welchen Vorteil hat die zustandsabhängige Instandhaltung?","w":"Der Zustand wird durch Inspektion oder Überwachung erfasst. Das kostet Aufwand, vermeidet aber zu frühen Austausch und ungeplante Stillstände.","o":["Sie kommt ohne Inspektionen und Messungen aus","Bauteile werden erst kurz vor der Abnutzungsgrenze getauscht, der Abnutzungsvorrat wird gut genutzt","Ausfälle sind vollständig ausgeschlossen","Bauteile werden grundsätzlich in festen Zeitabständen getauscht"],"r":1},{"id":"IM-ih-06","teil":"IMF","g":"imih","th":"Strategien","n":2,"q":"Für welche Bauteile ist die störungsbedingte Instandhaltung (Betrieb bis zum Ausfall) vertretbar?","w":"Bei sicherheitsrelevanten Bauteilen und teuren Folgeschäden wird vorbeugend instand gehalten.","o":["Für Bremsen und Sicherheitseinrichtungen","Für Engpassmaschinen ohne Ersatz","Für billige, schnell tauschbare Teile, deren Ausfall weder Sicherheit noch Produktion gefährdet","Für Bauteile, deren Ausfall teure Folgeschäden auslöst"],"r":2},{"id":"IM-ih-07","teil":"IMF","g":"imih","th":"Ausfallverhalten","n":2,"q":"Welche drei Phasen zeigt die Ausfallrate technischer Systeme über der Betriebszeit (Badewannenkurve)?","w":"Am Anfang fallen Teile mit Fertigungs- oder Montagefehlern aus, dann ist die Ausfallrate niedrig und nahezu konstant, am Ende steigt sie durch Verschleiß.","o":["Verschleißausfälle, Frühausfälle, Zufallsausfälle","Zufallsausfälle, Verschleißausfälle, Frühausfälle","Planausfälle, Wartungsausfälle, Restausfälle","Frühausfälle, Zufallsausfälle, Verschleißausfälle"],"r":3},{"id":"IM-ih-08","teil":"IMF","g":"imih","th":"Fehlersuche","n":1,"q":"Eine Anlage steht mit einer Störung. Womit beginnt die systematische Fehlersuche?","w":"Erst eingrenzen, dann eingreifen. Danach folgen Sichtprüfung und gezieltes Prüfen entlang des Energie- und Signalflusses, vom Einfachen zum Aufwendigen.","o":["Anlage sichern und Informationen sammeln: Bediener befragen, Störmeldung und Unterlagen auswerten","Sofort das teuerste Bauteil tauschen","Alle Ventile nacheinander ausbauen","Die Einstellungen aller Drosseln verändern, bis die Anlage läuft"],"r":0},{"id":"IM-ih-09","teil":"IMF","g":"imih","th":"Schadensbilder","n":3,"q":"Ein Wälzlager wird unmittelbar nach dem Nachschmieren mit viel Fett deutlich wärmer als vorher. Was ist die wahrscheinliche Ursache?","w":"Zu viel Fett muss von den Wälzkörpern ständig verdrängt werden. Die Schmierstoffmenge nach Herstellerangabe ist einzuhalten.","o":["Das Fett kühlt das Lager zu stark","Überfettung: Das überschüssige Fett wird gewalkt und erzeugt Wärme","Das Lager hat zu viel Spiel","Die Welle dreht zu langsam"],"r":1},{"id":"IM-ih-10","teil":"IMF","g":"imih","th":"Schmierung","n":1,"q":"Welche Angaben enthält ein Schmierplan?","w":"Der Schmierplan ist Teil der Wartungsunterlagen. Falsche oder gemischte Schmierstoffe können Lager und Dichtungen schädigen.","o":["Toleranzen und Oberflächenangaben","Schmierstellen, Schmierstoff, Menge und Schmierintervall","Schnittdaten und Werkzeuge","Preise und Lieferanten der Ersatzteile"],"r":1},{"id":"IM-ih-11","teil":"IMF","g":"imih","th":"Verschleiß","n":3,"q":"An den Zahnflanken eines Getriebes zeigen sich nach langer Laufzeit kleine Ausbrüche (Grübchen, Pittings). Welcher Verschleißmechanismus liegt vor?","w":"Die ständig wechselnde Flächenpressung ermüdet die Randschicht, Teilchen brechen aus. Fressen zeigt Riefen und Aufschweißungen, Abrasion gleichmäßige Kratzspuren.","o":["Oberflächenzerrüttung (Werkstoffermüdung)","Adhäsion (Fressen)","Abrasion durch Schleifstaub","Korrosion durch Kondenswasser"],"r":0},{"id":"IM-ih-12","teil":"IMF","g":"imih","th":"Reibung","n":2,"q":"Bei welchem Reibungszustand ist der Verschleiß am geringsten?","w":"Bei Flüssigkeitsreibung trennt ein tragender Schmierfilm die Gleitflächen vollständig. Mischreibung tritt beim Anfahren und Auslaufen auf.","o":["Trockenreibung","Mischreibung","Grenzreibung","Flüssigkeitsreibung"],"r":3},{"id":"IM-ih-13","teil":"IMF","g":"imih","th":"Kennzahlen","n":2,"q":"Eine Maschine war in einem Monat 190 Stunden in Betrieb und 10 Stunden durch Störungen ausgefallen. Wie groß ist die Verfügbarkeit?","w":"Verfügbarkeit = Betriebszeit / (Betriebszeit + Ausfallzeit) = 190 h / 200 h = 0,95 = 95 %.","o":["90 %","5 %","95 %","105 %"],"r":2},{"id":"IM-ih-14","teil":"IMF","g":"imih","th":"Riementrieb","n":2,"q":"An einem Antrieb mit drei parallel laufenden Keilriemen ist ein Riemen gerissen. Was ist richtig?","w":"Gebrauchte Riemen sind gelängt. Ein neuer, kürzerer Riemen würde die Last allein tragen und schnell ausfallen.","o":["Nur den gerissenen Riemen ersetzen","Alle drei Riemen als Satz ersetzen","Mit zwei Riemen und höherer Vorspannung weiterfahren","Den gerissenen Riemen kleben"],"r":1},{"id":"IM-ih-15","teil":"IMF","g":"imih","th":"Dokumentation","n":1,"q":"Warum werden Instandhaltungsarbeiten dokumentiert?","w":"Aus der Maschinenhistorie lassen sich Intervalle anpassen, Ersatzteile planen und Verbesserungen ableiten.","o":["Als Nachweis und um Schwachstellen und wiederkehrende Fehler zu erkennen","Damit die Maschine länger stillsteht","Weil sonst kein Schmierstoff bestellt werden darf","Um die Zeichnung des Herstellers zu ersetzen"],"r":0},{"id":"IM-ih-16","teil":"IMF","g":"imih","th":"Zustandsüberwachung","n":2,"q":"Mit welchem Verfahren lassen sich beginnende Wälzlagerschäden im laufenden Betrieb früh erkennen?","w":"Schäden an Laufbahnen und Wälzkörpern erzeugen kennzeichnende Schwingungen, lange bevor das Lager heiß oder laut wird.","o":["Messen der Wellenlänge mit dem Stahlmaßstab","Wiegen des Lagergehäuses","Härteprüfung am Lageraußenring","Schwingungsmessung (Körperschallmessung)"],"r":3},{"id":"IM-ih-17","teil":"IMF","g":"imih","th":"Kennzahlen","n":2,"q":"Eine Anlage lief 600 Betriebsstunden und hatte in dieser Zeit 4 Ausfälle. Wie groß ist die mittlere Betriebsdauer zwischen zwei Ausfällen (MTBF)?","w":"MTBF = Betriebszeit / Anzahl der Ausfälle = 600 h / 4 = 150 h.","o":["2400 h","604 h","150 h","0,0067 h"],"r":2},{"id":"IM-ih-N01","teil":"IMF","g":"imih","th":"Kennzahlen","n":2,"q":"Eine Maschine war von 160 geplanten Stunden 152 Stunden verfügbar. Berechnen Sie die Verfügbarkeit in Prozent.","w":"152 h / 160 h = 0,95 = 95 %.","ans":95,"u":"%","tol":0.02},{"id":"IM-qm-01","teil":"IMF","g":"imqm","th":"Grundbegriffe","n":1,"q":"Was bedeutet Qualität im Sinne des Qualitätsmanagements?","w":"Qualität heißt nicht so genau wie möglich, sondern so genau wie gefordert.","o":["Der Grad, in dem ein Produkt die gestellten Anforderungen erfüllt","Die höchste erreichbare Genauigkeit, unabhängig von den Kosten","Der höchste Preis am Markt","Die größte Stückzahl je Schicht"],"r":0},{"id":"IM-qm-02","teil":"IMF","g":"imqm","th":"Verbesserung","n":1,"q":"In welcher Reihenfolge laufen die Schritte des PDCA-Kreises ab?","w":"Plan, Do, Check, Act: Der Kreis wird immer wieder durchlaufen und beschreibt die ständige Verbesserung.","o":["Ausführen, Planen, Handeln, Überprüfen","Überprüfen, Handeln, Planen, Ausführen","Planen, Überprüfen, Ausführen, Handeln","Planen, Ausführen, Überprüfen, Handeln"],"r":3},{"id":"IM-qm-03","teil":"IMF","g":"imqm","th":"Prüfmittelüberwachung","n":2,"q":"Was geschieht beim Kalibrieren eines Messgeräts?","w":"Das Einstellen heißt Justieren, die behördliche Prüfung Eichen. Kalibrierte Prüfmittel tragen eine Kennzeichnung mit dem nächsten Prüftermin.","o":["Das Gerät wird so eingestellt, dass die Abweichung möglichst klein wird","Eine Behörde prüft und stempelt das Gerät","Die Abweichung der Anzeige vom richtigen Wert wird festgestellt und dokumentiert, ohne das Gerät zu verändern","Das Gerät wird gereinigt und geölt"],"r":2},{"id":"IM-qm-04","teil":"IMF","g":"imqm","th":"Prüfmittelwahl","n":2,"q":"Ein Maß hat die Toleranz 0,1 mm. Nach der Faustregel soll der Skalenteilungswert des Prüfmittels höchstens ein Zehntel der Toleranz betragen. Welches Prüfmittel erfüllt das?","w":"0,1 mm / 10 = 0,01 mm. Nur die Bügelmessschraube löst so fein auf.","o":["Stahlmaßstab mit 0,5 mm Teilung","Bügelmessschraube mit 0,01 mm Skalenteilungswert","Messschieber mit 0,1 mm Noniuswert","Messschieber mit 0,05 mm Noniuswert"],"r":1},{"id":"IM-qm-05","teil":"IMF","g":"imqm","th":"Prüfumfang","n":2,"q":"Wann ist eine 100-%-Prüfung statt einer Stichprobenprüfung angebracht?","w":"Bei zerstörender Prüfung ist nur eine Stichprobe möglich. Die 100-%-Prüfung ist teuer und wird auf wichtige Merkmale oder unsichere Prozesse beschränkt.","o":["Bei sicherheitskritischen Merkmalen","Bei jedem Normteil aus dem Lager","Bei zerstörender Prüfung","Immer dann, wenn die Stückzahl sehr groß ist"],"r":0},{"id":"IM-qm-06","teil":"IMF","g":"imqm","th":"Statistik","n":1,"q":"Fünf Messwerte eines Durchmessers lauten 20,02 mm, 20,04 mm, 19,98 mm, 20,00 mm und 20,06 mm. Wie groß ist der arithmetische Mittelwert?","w":"Summe 100,10 mm, geteilt durch 5 ergibt 20,02 mm.","o":["20,00 mm","20,04 mm","20,10 mm","20,02 mm"],"r":3},{"id":"IM-qm-07","teil":"IMF","g":"imqm","th":"Statistik","n":1,"q":"Fünf Messwerte eines Durchmessers lauten 20,02 mm, 20,04 mm, 19,98 mm, 20,00 mm und 20,06 mm. Wie groß ist die Spannweite?","w":"Spannweite R = größter Wert - kleinster Wert = 20,06 mm - 19,98 mm = 0,08 mm.","o":["0,02 mm","0,04 mm","0,08 mm","0,06 mm"],"r":2},{"id":"IM-qm-08","teil":"IMF","g":"imqm","th":"Regelkarte","n":2,"q":"Wozu dient eine Qualitätsregelkarte?","w":"Stichprobenwerte werden fortlaufend eingetragen. Trends oder Werte außerhalb der Eingriffsgrenzen zeigen, dass in den Prozess eingegriffen werden muss.","o":["Sie ersetzt die Zeichnung am Arbeitsplatz","Sie überwacht einen Fertigungsprozess über die Zeit und zeigt Veränderungen, bevor Ausschuss entsteht","Sie listet die Ersatzteile einer Maschine auf","Sie regelt die Drehzahl der Maschine selbsttätig"],"r":1},{"id":"IM-qm-09","teil":"IMF","g":"imqm","th":"Prozessfähigkeit","n":3,"q":"Ein Merkmal hat die Toleranz T = 0,12 mm, die Standardabweichung des Prozesses beträgt s = 0,01 mm. Wie groß ist der Prozessfähigkeitsindex cp = T / (6 · s)?","w":"cp = 0,12 mm / (6 · 0,01 mm) = 2,0. Üblich ist die Forderung cp mindestens 1,33.","o":["2,0","12","0,5","1,2"],"r":0},{"id":"IM-qm-10","teil":"IMF","g":"imqm","th":"Qualitätswerkzeuge","n":2,"q":"Wozu dient ein Ursache-Wirkungs-Diagramm (Ishikawa-Diagramm)?","w":"Die Fischgrätendarstellung hilft dem Team, keine Ursachengruppe zu übersehen.","o":["Mögliche Ursachen eines Problems geordnet sammeln, zum Beispiel nach Mensch, Maschine, Material, Methode","Die zeitliche Lage von Arbeitsgängen darstellen","Messwerte einer Stichprobe mitteln","Die Kosten eines Auftrags berechnen"],"r":0},{"id":"IM-qm-11","teil":"IMF","g":"imqm","th":"Qualitätswerkzeuge","n":2,"q":"Was zeigt ein Pareto-Diagramm?","w":"Die Balken sind nach Größe sortiert. So wird sichtbar, welche Fehler zuerst bearbeitet werden sollten.","o":["Den Verlauf eines Messwerts über die Zeit","Fehlerarten nach Häufigkeit oder Kosten geordnet: Wenige Ursachen verursachen den größten Teil der Fehler","Den Zusammenhang zwischen Drehzahl und Drehmoment","Die Reihenfolge der Montageschritte"],"r":1},{"id":"IM-qm-12","teil":"IMF","g":"imqm","th":"Selbstprüfung","n":1,"q":"Welchen Vorteil hat die Werkerselbstprüfung?","w":"Wer selbst prüft, erkennt Abweichungen früh und kann den Prozess gleich korrigieren. Das senkt die Fehlerkosten.","o":["Prüfmittel müssen nicht mehr überwacht werden","Die Endprüfung entfällt in jedem Fall","Fehler werden direkt am Arbeitsplatz erkannt und sofort abgestellt","Die Toleranzen dürfen größer gewählt werden"],"r":2},{"id":"IM-qm-13","teil":"IMF","g":"imqm","th":"Gut, Nacharbeit, Ausschuss","n":2,"q":"Eine Welle hat das Maß Ø30 mit den Abmaßen -0,02 mm und -0,05 mm. Gemessen wird 29,99 mm. Wie ist das Teil zu bewerten?","w":"Höchstmaß 29,98 mm, Mindestmaß 29,95 mm. Die Welle ist noch zu dick und kann nachgearbeitet werden. Unter dem Mindestmaß wäre sie Ausschuss.","o":["Gut: Das Istmaß liegt in der Toleranz","Ausschuss: Das Istmaß liegt unter dem Mindestmaß","Gut: Entscheidend ist nur das Nennmaß","Nacharbeit: Das Istmaß liegt über dem Höchstmaß 29,98 mm"],"r":3},{"id":"IM-qm-14","teil":"IMF","g":"imqm","th":"Fehlerkosten","n":2,"q":"Was besagt die Zehnerregel der Fehlerkosten?","w":"Ein Fehler, der in der Planung wenig kostet, wird in der Fertigung teurer und beim Kunden am teuersten. Deshalb lohnt sich Fehlervermeidung.","o":["Je später ein Fehler entdeckt wird, desto teurer wird seine Beseitigung, etwa um den Faktor 10 je Stufe","Jedes zehnte Teil muss geprüft werden","Zehn Prozent der Teile dürfen fehlerhaft sein","Ein Prüfmittel muss zehnmal so teuer sein wie das Werkstück"],"r":0},{"id":"IM-qm-15","teil":"IMF","g":"imqm","th":"Audit","n":2,"q":"Was ist ein Qualitätsaudit?","w":"Audits prüfen Systeme, Prozesse oder Produkte anhand von Nachweisen. Abweichungen führen zu Korrekturmaßnahmen.","o":["Eine Messung jedes gefertigten Teils","Eine systematische, unabhängige Untersuchung, ob festgelegte Anforderungen erfüllt werden","Eine Schulung für neue Mitarbeiter","Eine Reklamation des Kunden"],"r":1},{"id":"IM-qm-16","teil":"IMF","g":"imqm","th":"Prüfplan","n":1,"q":"Was legt ein Prüfplan fest?","w":"Der Prüfplan nennt Prüfmerkmal, Prüfmittel, Prüfumfang, Prüfzeitpunkt und die Art der Dokumentation.","o":["Mit welchen Schnittdaten gefertigt wird","Wer wann Urlaub hat","Welche Merkmale womit, wann und wie oft geprüft werden","Welche Schmierstoffe verwendet werden"],"r":2},{"id":"IM-qm-N01","teil":"IMF","g":"imqm","th":"Prozessfähigkeit","n":3,"q":"Ein Merkmal hat die Toleranz 0,2 mm, die Standardabweichung beträgt 0,02 mm. Berechnen Sie den Prozessfähigkeitsindex cp = T / (6 · s).","w":"cp = 0,2 mm / (6 · 0,02 mm) = 0,2 / 0,12 ≈ 1,67.","ans":1.667,"u":"","tol":0.02}]};
